# builder/gen_ch26_p3.py
# -*- coding: utf-8 -*-

exercises = [{'num': 81, 'title': 'Фаззинг-тестирование (testing.F) JSON-хендлера на устойчивость к сбоям', 'task': 'Напишите Fuzz-тест (`testing.F`) для вашего хендлера, который парсит JSON, чтобы найти входные данные, вызывающие панику или падение сервера.', 'theory': 'Фаззинг (Fuzzing) встроен в инструмент `go test` начиная с Go 1.18. Движок генерирует случайные мутированные байтовые последовательности и подает их на вход хендлеру. Главная цель — доказать, что сервер возвращает корректную ошибку (400 Bad Request) и никогда не падает в панику при получении битого или вредоносного payload.', 'step_by_step': '1. Опишем целевой хендлер разбора JSON.\n2. Продемонстрируем логику фаззинг-функции `FuzzJSONHandler(f *testing.F)`.\n3. Зададим начальный корпус семян `f.Add(...)`.\n4. В цикле фаззинга проверим отсутствие паник на случайных данных.', 'code_blocks': [{'filename': 'handler_fuzz_test.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype RegisterRequest struct {\n\tEmail string `json:"email"`\n\tAge   int    `json:"age"`\n}\n\nfunc parseUserHandler(w http.ResponseWriter, r *http.Request) {\n\tdefer r.Body.Close()\n\tvar req RegisterRequest\n\tif err := json.NewDecoder(r.Body).Decode(&req); err != nil {\n\t\thttp.Error(w, "bad json", http.StatusBadRequest)\n\t\treturn\n\t}\n\tw.WriteHeader(http.StatusOK)\n}\n\nfunc main() {\n\t// Демонстрация симулятора фаззинга на случайных байтах\n\ttestSeeds := [][]byte{\n\t\t[]byte(`{"email":"user@ya.ru","age":25}`),\n\t\t[]byte(`{"email":null,"age":-1}`),\n\t\t[]byte(`{broken_json...`),\n\t\t[]byte("\\x00\\xff\\xfe\\xfd"),\n\t\tbytes.Repeat([]byte("9"), 500),\n\t}\n\n\tfor i, seed := range testSeeds {\n\t\treq := httptest.NewRequest(http.MethodPost, "/register", bytes.NewReader(seed))\n\t\trec := httptest.NewRecorder()\n\n\t\t// Проверяем, что хендлер никогда не паникует\n\t\tfunc() {\n\t\t\tdefer func() {\n\t\t\t\tif r := recover(); r != nil {\n\t\t\t\t\tpanic(fmt.Sprintf("FATAL: Handler panicked on seed #%d: %v", i, r))\n\t\t\t\t}\n\t\t\t}()\n\t\t\tparseUserHandler(rec, req)\n\t\t}()\n\n\t\tfmt.Printf("Seed #%d: Status %d (No Panics!)\\n", i, rec.Code)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run handler_fuzz_test.go\n# Вывод:\n# Seed #0: Status 200 (No Panics!)\n# Seed #1: Status 200 (No Panics!)\n# Seed #2: Status 400 (No Panics!)\n# Seed #3: Status 400 (No Panics!)\n# Seed #4: Status 400 (No Panics!)'}], 'under_the_hood': 'Стандартный `go test -fuzz=Fuzz` использует покрытие кода (Coverage-guided Fuzzing), исследуя новые ветвления AST/SSA при изменении байтов входного среза.', 'pitfalls': 'Если в хендлере разыменовать `nil`-указатель или обратиться за границы среза без проверки длины, фаззер мгновенно найдет сбойный ввод и сохранит его в директорию `testdata/fuzz`.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен корпус семян (Corpus Seeds) в тестах testing.F?»\n**Ответ:** Корпус семян задает синтаксически верные начальные образцы валидных данных (`f.Add(...)`). Фаззер берет эти семена и начинает точечно мутировать байты (переворачивать биты, вставлять спецсимволы), быстрее находя глубокие краевые баги в парсерах.'}, {'num': 82, 'title': 'Декларативная валидация DTO с детальным возвратом ошибок 400', 'task': 'Реализуйте API с валидацией входных данных: при создании задачи проверяйте, что поле `title` не пустое, возвращайте ошибку 400 с описанием.', 'theory': 'Обработка ошибок валидации в продакшн API:\nКлиент должен получать структурированный ответ со списком всех невалидных полей, а не просто абстрактный статус 400:\n`{"error": "validation_failed", "details": {"title": "обязательное поле"}}`.', 'step_by_step': '1. Опишем структуру задачи и структуру валидационных ошибок.\n2. Проверим длину заголовка `strings.TrimSpace(title)`.\n3. Вернем JSON с описанием проблемы при ошибке.\n4. Проверим ответ на клиенте.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strings"\n)\n\ntype CreateTaskInput struct {\n\tTitle       string `json:"title"`\n\tPriority    int    `json:"priority"`\n}\n\ntype ValidationErrorResponse struct {\n\tError   string            `json:"error"`\n\tDetails map[string]string `json:"details"`\n}\n\nfunc createTaskWithValidation(w http.ResponseWriter, r *http.Request) {\n\tvar in CreateTaskInput\n\tif err := json.NewDecoder(r.Body).Decode(&in); err != nil {\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tw.WriteHeader(http.StatusBadRequest)\n\t\t_ = json.NewEncoder(w).Encode(map[string]string{"error": "malformed JSON"})\n\t\treturn\n\t}\n\n\terrors := make(map[string]string)\n\tif strings.TrimSpace(in.Title) == "" {\n\t\terrors["title"] = "поле title не может быть пустым"\n\t}\n\tif in.Priority < 1 || in.Priority > 5 {\n\t\terrors["priority"] = "priority должен быть в диапазоне от 1 до 5"\n\t}\n\n\tif len(errors) > 0 {\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tw.WriteHeader(http.StatusBadRequest)\n\t\t_ = json.NewEncoder(w).Encode(ValidationErrorResponse{\n\t\t\tError:   "validation_failed",\n\t\t\tDetails: errors,\n\t\t})\n\t\treturn\n\t}\n\n\tw.WriteHeader(http.StatusCreated)\n\tfmt.Fprint(w, `{"status":"created"}`)\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(createTaskWithValidation))\n\tdefer ts.Close()\n\n\t// Запрос с невалидными данными\n\tinvalidJSON := `{"title": "   ", "priority": 10}`\n\tres, _ := http.Post(ts.URL, "application/json", bytes.NewBufferString(invalidJSON))\n\tbody, _ := io.ReadAll(res.Body)\n\tres.Body.Close()\n\n\tfmt.Printf("[Status] %d\\n", res.StatusCode)\n\tfmt.Printf("[Body]   %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status] 400\n# [Body]   {"error":"validation_failed","details":{"priority":"priority должен быть в диапазоне от 1 до 5","title":"поле title не может быть пустым"}}'}], 'under_the_hood': 'Мапа ошибок `map[string]string` сериализуется в JSON-объект ключ-значение, легко разбираемый на стороне фронтенда для подсветки полей формы.', 'pitfalls': 'Не забывайте `strings.TrimSpace()`: строка из одних пробелов `"   "` имеет ненулевую длину, но фактически является пустой.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие валидации DTO на транспортном слое от валидации Domain Entity?»\n**Ответ:** DTO-валидация проверяет базовый синтаксис входных данных (формат email, наличие полей, типы). Доменная валидация проверяет бизнес-инварианты сущности (достаточно ли средств на счете, уникален ли логин в БД, не закрыт ли заказ).'}, {'num': 83, 'title': 'Мягкая остановка HTTP-сервера с сигналом SIGINT и фоновой горутиной ListenAndServe', 'task': '**Graceful Shutdown (Мягкая остановка)**: В `main` запусти `srv.ListenAndServe()` в горутине. В основной горутине жди сигнала `SIGINT` (Ctrl+C). При получении сигнала вызови `srv.Shutdown(ctx)`, чтобы сервер перестал принимать новые запросы, но дообработал текущие.', 'theory': 'Промышленный шаблон жизненного цикла HTTP-сервера в `main.go`:\n1. Создание сервера с обработчиком.\n2. Запуск слушателя в горутине `go func() { srv.ListenAndServe() }()`.\n3. Ожидание сигналов завершения в `main` горутине через `signal.NotifyContext`.\n4. Вызов `srv.Shutdown(ctx)` с таймаутом (например, 10 секунд).\n5. Освобождение ресурсов (БД, брокеры, кэш).', 'step_by_step': '1. Создадим структуру `&http.Server`.\n2. Запустим `srv.ListenAndServe` в горутине.\n3. Проинициализируем `signal.NotifyContext`.\n4. Дождемся отмены и вызовем `srv.Shutdown`.\n5. Протестируем сценарий завершения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"net/http"\n\t"time"\n)\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/api/process", func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(50 * time.Millisecond)\n\t\tfmt.Fprint(w, "Успешно обработано")\n\t})\n\n\tsrv := &http.Server{\n\t\tAddr:    "127.0.0.1:9033",\n\t\tHandler: mux,\n\t}\n\n\t// 1. Запуск в горутине\n\tserverErr := make(chan error, 1)\n\tgo func() {\n\t\tif err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {\n\t\t\tserverErr <- err\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\tfmt.Println("[Init] HTTP-сервер успешно слушает порт 9033")\n\n\t// 2. Имитируем получение сигнала SIGINT через 20 мс\n\ttime.Sleep(20 * time.Millisecond)\n\tfmt.Println("[Signal] Пойман сигнал завершения SIGINT")\n\n\t// 3. Graceful Shutdown с дедлайном 2 секунды\n\tshutdownCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)\n\tdefer cancel()\n\n\tif err := srv.Shutdown(shutdownCtx); err != nil {\n\t\tfmt.Printf("[Error] Сбой остановки: %v\\n", err)\n\t} else {\n\t\tfmt.Println("[Success] Сервер завершил работу без потери сетевых пакетов!")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Init] HTTP-сервер успешно слушает порт 9033\n# [Signal] Пойман сигнал завершения SIGINT\n# [Success] Сервер завершил работу без потери сетевых пакетов!'}], 'under_the_hood': '`srv.Shutdown` закрывает внутренний `net.Listener` и опрашивает открытые сокеты каждую секунду через таймер, пока счетчик не станет 0.', 'pitfalls': 'Если передать в `srv.Shutdown(ctx)` контекст без таймаута (`context.Background()`), сервер может зависнуть навсегда из-за медленного клиента, который никогда не закрывает соединение.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему srv.Close() не подходит для штатного деплоя сервиса?»\n**Ответ:** `srv.Close()` немедленно и грубо закрывает все TCP-соединения, обрывая запросы на середине передачи. Клиенты видят ошибку 502 или connection reset. `srv.Shutdown()` позволяет текущим запросам завершиться чисто.'}, {'num': 84, 'title': 'Тестирование Recovery Middleware: проверка статуса 500 и стабильности тестового раннера', 'task': 'Протестируйте ваш middleware (например, `Recovery`), намеренно вызвав панику в тестовом хендлере и проверив, что `Recorder` получил статус 500, а тест не упал.', 'theory': 'Тестирование перехвата паник:\nТестовый хендлер намеренно бросает `panic("test failure")`. Если middleware работает корректно:\n1. Тестовый процесс не аварийно падает.\n2. `rec.Code` равен `http.StatusInternalServerError` (500).\n3. В теле ответа содержится ожидаемый JSON с ошибкой.', 'step_by_step': '1. Создадим функцию `SafeRecoveryMiddleware`.\n2. Напишем тестовый хендлер с вызовом `panic`.\n3. Обернем его в middleware и выполним запрос через `httptest.NewRecorder()`.\n4. Проверим статус 500.', 'code_blocks': [{'filename': 'recovery_test.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc SafeRecovery(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tdefer func() {\n\t\t\tif rec := recover(); rec != nil {\n\t\t\t\tw.WriteHeader(http.StatusInternalServerError)\n\t\t\t\t_, _ = w.Write([]byte(`{"error":"recovered_from_panic"}`))\n\t\t\t}\n\t\t}()\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\t// Паникующий хендлер\n\tbadHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tpanic("nil pointer dereference simulation")\n\t})\n\n\twrapped := SafeRecovery(badHandler)\n\n\treq := httptest.NewRequest(http.MethodGet, "/crash", nil)\n\trec := httptest.NewRecorder()\n\n\t// Выполняем вызов\n\twrapped.ServeHTTP(rec, req)\n\n\tfmt.Printf("[Test Result] Получен статус: %d (Ожидается 500)\\n", rec.Code)\n\tfmt.Printf("[Test Result] Тело ошибки:    %s\\n", rec.Body.String())\n\tif rec.Code == http.StatusInternalServerError {\n\t\tfmt.Println("✔ ТЕСТ ПРОЙДЕН УСПЕШНО: Паника поймана, процесс остался жив!")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run recovery_test.go\n# Вывод:\n# [Test Result] Получен статус: 500 (Ожидается 500)\n# [Test Result] Тело ошибки:    {"error":"recovered_from_panic"}\n# ✔ ТЕСТ ПРОЙДЕН УСПЕШНО: Паника поймана, процесс остался жив!'}], 'under_the_hood': '`httptest.NewRecorder()` корректно перехватывает вызовы `w.WriteHeader(500)` даже внутри блоков `defer/recover`.', 'pitfalls': 'Если забыть вызвать `recover()`, паника вылетит наружу и весь `go test` аварийно упадет с кодом завершения 2.', 'bigtech_interview': '**Вопрос с собеседования:** «Как проверить в тесте, что паника была залогирована?»\n**Ответ:** Передать в `SafeRecovery` кастомный логгер (например, `slog.New(slog.NewTextHandler(&logBuf, nil))`), а в конце теста проверить, что буфер логов `logBuf.String()` содержит текст паники и стек-трейс.'}, {'num': 85, 'title': 'Архитектура современных WebSocket-библиотек: сравнение gorilla и nhooyr/websocket', 'task': 'Подключите современную библиотеку для работы с WebSocket (например, `nhooyr.io/websocket` или `github.com/coder/websocket`).', 'theory': 'Современные стандарты WebSocket в Go:\n- `nhooyr.io/websocket` (сейчас `coder/websocket`) — идиоматическая современная библиотека:\n  - Первоклассная поддержка `context.Context` во всех операциях чтения и записи.\n  - Нулевые аллокации при передаче буферов.\n  - Полноценная поддержка WebAssembly.\n  - Простой API: `c, err := websocket.Accept(w, r, nil)`.', 'step_by_step': '1. Покажем концепцию WebSocket-апгрейда через стандартный Hijacker.\n2. Продемонстрируем сигнатуру современного метода `websocket.Accept(w, r, opts)`.\n3. Покажем чтение и запись текстовых сообщений с контекстом.', 'code_blocks': [{'filename': 'ws_concept.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"time"\n)\n\n// Концептуальный интерфейс современного WebSocket соединения (похожий на coder/websocket)\ntype WSConn interface {\n\tRead(ctx context.Context) (messageType int, payload []byte, err error)\n\tWrite(ctx context.Context, messageType int, payload []byte) error\n\tClose(statusCode int, reason string) error\n}\n\nfunc handleWebSocketChat(w http.ResponseWriter, r *http.Request) {\n\t// В реальном коде:\n\t// conn, err := websocket.Accept(w, r, &websocket.AcceptOptions{\n\t//     OriginPatterns: []string{"company.com"},\n\t// })\n\t// if err != nil { return }\n\t// defer conn.Close(websocket.StatusInternalError, "the sky is falling")\n\n\tctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)\n\tdefer cancel()\n\n\tfmt.Printf("[WebSocket Handler] Готов к приему сообщений по протоколу WS. Context deadline: %v\\n", ctx)\n}\n\nfunc main() {\n\thttp.HandleFunc("/ws", handleWebSocketChat)\n\tfmt.Println("WebSocket эндпоинт /ws зарегистрирован с поддержкой context.Context")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run ws_concept.go\n# Вывод:\n# WebSocket эндпоинт /ws зарегистрирован с поддержкой context.Context'}], 'under_the_hood': '`coder/websocket` в отличие от старого `gorilla/websocket` не требует отдельных горутин для чтения пингов, автоматически обрабатывая Ping/Pong внутри вызовов `Read()`.', 'pitfalls': 'В `gorilla/websocket` одновременная запись в соединение из двух горутин запрещена (Data Race). В `coder/websocket` запись потокобезопасна.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в высоконагруженных WebSocket сервисах критична поддержка context.Context?»\n**Ответ:** Это позволяет устанавливать гибкие таймауты на каждую операцию записи (`conn.Write(ctx, ...)`), прерывая зависшие сокеты медленных клиентов без блокировки общей очереди сообщений.'}, {'num': 86, 'title': 'Первая Middleware: измерение времени ответа и структурированное логирование', 'task': '**Первая Middleware (Логирование)**: Middleware — это паттерн декоратора (функция принимает хендлер и возвращает хендлер). Напиши функцию `LoggingMiddleware`, которая замеряет время начала запроса, вызывает `next.ServeHTTP(w, r)` и логирует время выполнения, метод и URL. Оберни в неё свой роутер.', 'theory': 'Паттерн Декоратор (Decorator / Middleware):\nФункция декорирует интерфейс `http.Handler`, выполняя замер `start := time.Now()` перед вызовом и `time.Since(start)` после возврата управления.', 'step_by_step': '1. Напишем `LoggingMiddleware`.\n2. Замерим длительность через `time.Since`.\n3. Обернем `mux`.\n4. Выполним проверочный запрос.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc LoggingMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tstart := time.Now()\n\n\t\tnext.ServeHTTP(w, r)\n\n\t\telapsed := time.Since(start)\n\t\tfmt.Printf("[HTTP Request] %s %s -> Завершено за %v\\n", r.Method, r.URL.Path, elapsed.Round(time.Microsecond))\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/calc", func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\tfmt.Fprint(w, "calculated")\n\t})\n\n\tserver := httptest.NewServer(LoggingMiddleware(mux))\n\tdefer server.Close()\n\n\tresp, _ := http.Get(server.URL + "/calc")\n\tresp.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [HTTP Request] GET /calc -> Завершено за 5ms'}], 'under_the_hood': 'Вызов `time.Since(start)` использует монотонные часы процессора (Monotonic Clock), что защищает замер от скачков системного времени при синхронизации через NTP.', 'pitfalls': 'Не используйте тяжелые строковые конкатенации в горячих путях логгера: форматируйте логи через структурированный `log/slog`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему time.Now() в Go возвращает и настенные, и монотонные часы?»\n**Ответ:** Настенные часы (Wall clock) показывают реальное время суток и могут сдвигаться назад оператором или NTP. Монотонные часы (Monotonic clock) всегда идут строго вперед с константной скоростью тактов CPU, гарантируя корректность замеров `time.Since`.'}, {'num': 87, 'title': 'Версионирование API: поддержка эндпоинтов v1 и v2 на базе единого сервера', 'task': 'Добавьте версионирование API: `/api/v1/tasks` и `/api/v2/tasks` с разными форматами ответа. Используйте один сервер.', 'theory': 'Версионирование через URL-префиксы (`/v1/`, `/v2/`) — самый наглядный и практичный подход в современной микросервисной разработке. Он позволяет параллельно поддерживать старых клиентов мобильных приложений (v1) и развертывать новый оптимизированный формат данных (v2).', 'step_by_step': '1. Опишем структуру ответа для v1 (плоская структура).\n2. Опишем структуру для v2 (вложенный объект с метаданными).\n3. Зарегистрируем оба маршрута в одном `ServeMux`.\n4. Проверим запросы к обоим версиям API.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\n// Версия 1: простой список строк\nfunc tasksV1Handler(w http.ResponseWriter, r *http.Request) {\n\tw.Header().Set("Content-Type", "application/json")\n\tv1Data := []string{"Задача 1", "Задача 2"}\n\t_ = json.NewEncoder(w).Encode(v1Data)\n}\n\n// Версия 2: расширенный объект с метаданными и идентификаторами\ntype TaskV2 struct {\n\tID    int    `json:"id"`\n\tTitle string `json:"title"`\n}\n\ntype ResponseV2 struct {\n\tVersion string   `json:"version"`\n\tTasks   []TaskV2 `json:"tasks"`\n}\n\nfunc tasksV2Handler(w http.ResponseWriter, r *http.Request) {\n\tw.Header().Set("Content-Type", "application/json")\n\tv2Data := ResponseV2{\n\t\tVersion: "2.0.0",\n\t\tTasks: []TaskV2{\n\t\t\t{ID: 101, Title: "Задача 1"},\n\t\t\t{ID: 102, Title: "Задача 2"},\n\t\t},\n\t}\n\t_ = json.NewEncoder(w).Encode(v2Data)\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("GET /api/v1/tasks", tasksV1Handler)\n\tmux.HandleFunc("GET /api/v2/tasks", tasksV2Handler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tr1, _ := http.Get(ts.URL + "/api/v1/tasks")\n\tb1, _ := io.ReadAll(r1.Body)\n\tr1.Body.Close()\n\tfmt.Printf("[v1 Response] %s", string(b1))\n\n\tr2, _ := http.Get(ts.URL + "/api/v2/tasks")\n\tb2, _ := io.ReadAll(r2.Body)\n\tr2.Body.Close()\n\tfmt.Printf("[v2 Response] %s", string(b2))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [v1 Response] ["Задача 1","Задача 2"]\n# [v2 Response] {"version":"2.0.0","tasks":[{"id":101,"title":"Задача 1"},{"id":102,"title":"Задача 2"]}'}], 'under_the_hood': '`ServeMux` легко изолирует разные версии API благодаря поддержке точных путей и префиксов поддеревьев.', 'pitfalls': 'Не плодите десятки версий: устаревшие версии API (Deprecated) должны логировать предупреждения в заголовок `Warning: 299 - "API v1 is deprecated"` и планомерно выводиться из эксплуатации.', 'bigtech_interview': '**Вопрос с собеседования:** «Какие еще бывают способы версионирования REST API кроме URL-пути?»\n**Ответ:** 1. Через заголовки запроса (`Accept: application/vnd.company.v2+json` — Content Negotiation). 2. Через кастомный заголовок (`X-API-Version: 2`). URL-версионирование (`/v1/...`) популярнее всего, так как легко кэшируется CDN и прозрачно для разработчиков.'}, {'num': 88, 'title': 'Механика Upgrade HTTP-соединения до WebSocket по протоколу RFC 6455', 'task': 'Реализуйте HTTP-хендлер, который "апгрейдит" HTTP-соединение до WebSocket (`websocket.Accept`).', 'theory': 'Протокол рукопожатия WebSocket (Handshake):\n1. Клиент шлет HTTP GET запрос с заголовками `Upgrade: websocket` и `Connection: Upgrade`, а также случайным ключом `Sec-WebSocket-Key`.\n2. Сервер рассчитывает ответный ключ `Sec-WebSocket-Accept = base64(sha1(key + GUID))`.\n3. Сервер возвращает статус `101 Switching Protocols`.\n4. Соединение переключается в режим обмена фреймами.', 'step_by_step': '1. Создадим HTTP-хендлер `/ws`.\n2. Проверим заголовки рукопожатия.\n3. Рассчитаем хеш SHA-1 по стандарту RFC 6455.\n4. Отправим ответ 101 Switching Protocols.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/sha1"\n\t"encoding/base64"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"strings"\n)\n\nconst websocketGUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"\n\nfunc computeAcceptKey(clientKey string) string {\n\th := sha1.New()\n\th.Write([]byte(clientKey + websocketGUID))\n\treturn base64.StdEncoding.EncodeToString(h.Sum(nil))\n}\n\nfunc wsUpgradeHandler(w http.ResponseWriter, r *http.Request) {\n\tif !strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {\n\t\thttp.Error(w, "Expected Upgrade: websocket", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tclientKey := r.Header.Get("Sec-WebSocket-Key")\n\tif clientKey == "" {\n\t\thttp.Error(w, "Missing Sec-WebSocket-Key", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tacceptKey := computeAcceptKey(clientKey)\n\n\t// Отправляем рукопожатие апгрейда 101\n\tw.Header().Set("Upgrade", "websocket")\n\tw.Header().Set("Connection", "Upgrade")\n\tw.Header().Set("Sec-WebSocket-Accept", acceptKey)\n\tw.WriteHeader(http.StatusSwitchingProtocols)\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(wsUpgradeHandler))\n\tdefer ts.Close()\n\n\treq, _ := http.NewRequest(http.MethodGet, ts.URL, nil)\n\treq.Header.Set("Upgrade", "websocket")\n\treq.Header.Set("Connection", "Upgrade")\n\treq.Header.Set("Sec-WebSocket-Key", "dGhlIHNhbXBsZSBub25jZQ==")\n\n\tres, _ := http.DefaultClient.Do(req)\n\tdefer res.Body.Close()\n\n\tfmt.Printf("[Статус рукопожатия] %d (%s)\\n", res.StatusCode, res.Status)\n\tfmt.Printf("[Sec-WebSocket-Accept] %s\\n", res.Header.Get("Sec-WebSocket-Accept"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Статус рукопожатия] 101 (101 Switching Protocols)\n# [Sec-WebSocket-Accept] s3pPLMBiTxaQ9kYGzzhZRbK+xOo='}], 'under_the_hood': 'Магическая константа GUID `"258EAFA5-..."` зафиксирована в спецификации RFC 6455 для подтверждения того, что сервер действительно понимает протокол WebSocket.', 'pitfalls': 'Заголовок `Upgrade` регистронезависим, поэтому проверять его нужно через `strings.EqualFold(h, "websocket")`.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен расчет Sec-WebSocket-Accept через SHA-1 хэш от ключа клиента?»\n**Ответ:** Чтобы исключить ложный апгрейд старыми кэширующими прокси-серверами, которые могли бы по ошибке вернуть закэшированный ответ 101 на обычный HTTP-запрос.'}, {'num': 89, 'title': 'Генерация Self-Signed X.509 сертификата и запуск HTTPS-сервера в чистом Go', 'task': 'Сгенерируй **self-signed сертификат** через Go (`crypto/rsa`, `crypto/x509`, `crypto/x509/pkix`, `math/big`, `time`, `encoding/pem`). Сохрани `cert.pem` и `key.pem`. Напиши HTTPS-сервер, использующий их.', 'theory': 'Пакет `crypto/x509` в Go позволяет программно сгенерировать самоподписанный TLS-сертификат без использования утилит OpenSSL:\n1. Генерация RSA-ключа: `rsa.GenerateKey(rand.Reader, 2048)`.\n2. Заполнение шаблона `x509.Certificate` (Subject, NotBefore, NotAfter, IPAddresses).\n3. Создание сертификата: `x509.CreateCertificate(...)`.\n4. Сериализация в PEM-блоки `encoding/pem`.', 'step_by_step': '1. Сгенерируем приватный RSA ключ.\n2. Создадим X.509 сертификат для `127.0.0.1`.\n3. Запишем файлы `cert.pem` и `key.pem`.\n4. Запустим тестовый TLS-сервер.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/rand"\n\t"crypto/rsa"\n\t"crypto/tls"\n\t"crypto/x509"\n\t"crypto/x509/pkix"\n\t"encoding/pem"\n\t"fmt"\n\t"math/big"\n\t"net"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"time"\n)\n\nfunc generateSelfSignedCerts() (certFile, keyFile string, err error) {\n\tpriv, err := rsa.GenerateKey(rand.Reader, 2048)\n\tif err != nil {\n\t\treturn "", "", err\n\t}\n\n\ttemplate := x509.Certificate{\n\t\tSerialNumber: big.NewInt(1),\n\t\tSubject: pkix.Name{\n\t\t\tOrganization: []string{"Go Test Org"},\n\t\t\tCommonName:   "127.0.0.1",\n\t\t},\n\t\tNotBefore:             time.Now(),\n\t\tNotAfter:              time.Now().Add(24 * time.Hour),\n\t\tKeyUsage:              x509.KeyUsageKeyEncipherment | x509.KeyUsageDigitalSignature,\n\t\tExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},\n\t\tBasicConstraintsValid: true,\n\t\tIPAddresses:           []net.IP{net.ParseIP("127.0.0.1")},\n\t}\n\n\tderBytes, err := x509.CreateCertificate(rand.Reader, &template, &template, &priv.PublicKey, priv)\n\tif err != nil {\n\t\treturn "", "", err\n\t}\n\n\tcertOut, _ := os.CreateTemp("", "cert_*.pem")\n\t_ = pem.Encode(certOut, &pem.Block{Type: "CERTIFICATE", Bytes: derBytes})\n\tcertOut.Close()\n\n\tkeyOut, _ := os.CreateTemp("", "key_*.pem")\n\t_ = pem.Encode(keyOut, &pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(priv)})\n\tkeyOut.Close()\n\n\treturn certOut.Name(), keyOut.Name(), nil\n}\n\nfunc main() {\n\tcertFile, keyFile, err := generateSelfSignedCerts()\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer os.Remove(certFile)\n\tdefer os.Remove(keyFile)\n\n\tfmt.Println("Сгенерированы сертификаты:", certFile, keyFile)\n\n\t// Проверяем загрузку пары ключей\n\tcert, err := tls.LoadX509KeyPair(certFile, keyFile)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tserver := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "HTTPS Secure Response")\n\t}))\n\tserver.TLS = &tls.Config{Certificates: []tls.Certificate{cert}}\n\tserver.StartTLS()\n\tdefer server.Close()\n\n\t// Клиент с доверием к тестовому сертификату\n\tclient := server.Client()\n\tresp, err := client.Get(server.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tfmt.Printf("[HTTPS Success] Статус ответа: %d\\n", resp.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сгенерированы сертификаты: /tmp/cert_... /tmp/key_...\n# [HTTPS Success] Статус ответа: 200'}], 'under_the_hood': '`tls.LoadX509KeyPair` парсит ASN.1 DER байты внутри PEM-контейнеров и собирает структуру `tls.Certificate` для SSL/TLS рукопожатия.', 'pitfalls': 'В современных версиях Go поле `CommonName` считается устаревшим: браузеры требуют обязательного указания IP или DNS в `IPAddresses` или `DNSNames` (Subject Alternative Name, SAN).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go 1.15+ валидатор сертификатов отклоняет сертификаты без поля Subject Alternative Name (SAN)?»\n**Ответ:** По стандарту RFC 2818 поле Common Name признано устаревшим и уязвимым к подделке имен. Go форсирует проверку SAN для соответствия современным стандартам безопасности TLS.'}, {'num': 90, 'title': 'Хендлер регистрации /register: строгая валидация метода и тела запроса', 'task': '**Прием и валидация JSON**: Напишите API-обработчик `/register`. Он должен принимать только POST-запросы с телом в формате JSON, содержащим поля `Username` и `Password`. Используйте `json.NewDecoder` для парсинга тела запроса. Если поля пустые или запрос отправлен методом GET, верните клиенту ошибку `400 Bad Request` с описанием проблемы.', 'theory': 'Реализация защищенной регистрации:\n1. Проверка метода `r.Method == http.MethodPost` (или маршрут `POST /register` в Go 1.22).\n2. Защита от OOM через `http.MaxBytesReader`.\n3. Парсинг `json.NewDecoder`.\n4. Проверка минимальной длины пароля и непустого логина.', 'step_by_step': '1. Создадим обработчик `registerHandler`.\n2. Заблокируем GET-запросы.\n3. Проверим поля `Username` и `Password`.\n4. Протестируем сценарии успешной и невалидной регистрации.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strings"\n)\n\ntype RegisterDTO struct {\n\tUsername string `json:"username"`\n\tPassword string `json:"password"`\n}\n\nfunc registerHandler(w http.ResponseWriter, r *http.Request) {\n\tif r.Method != http.MethodPost {\n\t\thttp.Error(w, "Метод не поддерживается: ожидается POST", http.StatusMethodNotAllowed)\n\t\treturn\n\t}\n\n\tvar dto RegisterDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\thttp.Error(w, "Невалидный JSON формат", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tdto.Username = strings.TrimSpace(dto.Username)\n\tdto.Password = strings.TrimSpace(dto.Password)\n\n\tif dto.Username == "" || dto.Password == "" {\n\t\thttp.Error(w, "Поля username и password обязательны для заполнения", http.StatusBadRequest)\n\t\treturn\n\t}\n\tif len(dto.Password) < 6 {\n\t\thttp.Error(w, "Пароль должен содержать не менее 6 символов", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tw.Header().Set("Content-Type", "application/json")\n\tw.WriteHeader(http.StatusCreated)\n\tfmt.Fprintf(w, `{"status":"registered","username":"%s"}`, dto.Username)\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(registerHandler))\n\tdefer ts.Close()\n\n\t// 1. Попытка GET запроса\n\tr1, _ := http.Get(ts.URL)\n\tfmt.Printf("[GET Attempt] Status: %d\\n", r1.StatusCode)\n\tr1.Body.Close()\n\n\t// 2. Успешный POST\n\tbody := bytes.NewBufferString(`{"username":"developer","password":"super_secure_pass"}`)\n\tr2, _ := http.Post(ts.URL, "application/json", body)\n\tb2, _ := io.ReadAll(r2.Body)\n\tr2.Body.Close()\n\tfmt.Printf("[POST Valid]   Status: %d, Body: %s\\n", r2.StatusCode, string(b2))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [GET Attempt] Status: 405\n# [POST Valid]   Status: 201, Body: {"status":"registered","username":"developer"}'}], 'under_the_hood': 'Спецификация HTTP обязывает при возврате 405 указывать заголовок `Allow: POST`.', 'pitfalls': 'Никогда не логируйте значение поля `Password` в логи сервера при ошибках!', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go для паролей рекомендуют использовать []byte вместо string?»\n**Ответ:** Строки в Go неизменяемы (immutable) и могут оставаться в памяти кучи до следующего цикла сборщика мусора. Срез `[]byte` можно после использования немедленно занулить в памяти (`clear(buf)`), исключив кражу паролей через дамп памяти процесса.'}, {'num': 91, 'title': 'Auth Middleware с мгновенным отклонением неавторизованных запросов', 'task': '**Auth Middleware**: Напиши мидлварь, которая проверяет заголовок `Authorization`. Если токена нет — сразу отвечает `http.StatusUnauthorized` (401) и **не вызывает** `next.ServeHTTP`.', 'theory': 'Паттерн Guard / Gatekeeper Middleware:\nЕсли входное условие безопасности не выполнено, запрос немедленно сбрасывается со статусом 401. Следующий обработчик `next.ServeHTTP` никогда не вызывается.', 'step_by_step': '1. Создадим `StrictAuthMiddleware`.\n2. Проверим заголовок `Authorization`.\n3. При отсутствии вернем 401 и сделаем `return`.\n4. Проверим отсутствие выполнения защищенного хендлера.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc StrictAuthMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tif r.Header.Get("Authorization") == "" {\n\t\t\t// Мгновенный сброс без вызова next\n\t\t\tw.Header().Set("WWW-Authenticate", `Bearer realm="API"`)\n\t\t\thttp.Error(w, "Требуется заголовок Authorization", http.StatusUnauthorized)\n\t\t\treturn\n\t\t}\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc secretResource(w http.ResponseWriter, r *http.Request) {\n\tfmt.Println(" !!! ЭТОТ КОД НЕ ДОЛЖЕН ВЫПОЛНИТЬСЯ БЕЗ ТОКЕНА !!!")\n\tfmt.Fprint(w, "Секретные данные")\n}\n\nfunc main() {\n\thandler := StrictAuthMiddleware(http.HandlerFunc(secretResource))\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\tres, _ := http.Get(ts.URL)\n\tres.Body.Close()\n\n\tfmt.Println("Запрос без заголовка отклонен со статусом:", res.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запрос без заголовка отклонен со статусом: 401'}], 'under_the_hood': 'Оператор `return` после `http.Error` прерывает выполнение горутины в middleware, не допуская вызова внутренних слоев.', 'pitfalls': 'Забытый `return` после отправки ошибки — распространенный баг, приводящий к выполнению приватного кода.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между статус-кодами 401 Unauthorized и 403 Forbidden?»\n**Ответ:** `401 Unauthorized` означает «вы не аутентифицированы, представьтесь (токен отсутствует или невалиден)». `403 Forbidden` означает «вы успешно аутентифицированы, сервер знает кто вы, но у вашей роли нет прав доступа к этому ресурсу».'}, {'num': 92, 'title': 'Риски InsecureSkipVerify и безопасная альтернатива с добавлением RootCAs', 'task': 'Напиши **HTTPS-клиент**, который принимает self-signed сертификат: `tls.Config{InsecureSkipVerify: true}`. Объясни, почему это **небезопасно** для production. Покажи альтернативу: `RootCAs` с кастомным сертификатом.', 'theory': 'Опасность `InsecureSkipVerify: true`:\nФлаг отключает проверку подлинности сертификата сервера. Клиент подключается к ЛЮБОМУ серверу, делая соединение уязвимым к атакам Man-in-the-Middle (MitM).\nБезопасная альтернатива в продакшене — доверить конкретному корпоративному центру сертификации через `tls.Config{RootCAs: certPool}`.', 'step_by_step': '1. Создадим тестовый TLS-сервер.\n2. Продемонстрируем подключение с `InsecureSkipVerify: true`.\n3. Покажем безопасное решение с добавлением сертификата в `x509.NewCertPool()`.\n4. Проверим оба клиента.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/tls"\n\t"crypto/x509"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\t// Поднимаем TLS сервер с самоподписанным сертификатом\n\tserver := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Secure Data")\n\t}))\n\tdefer server.Close()\n\n\t// 1. ОПАСНЫЙ СПОСОБ: InsecureSkipVerify (риск MitM)\n\tinsecureClient := &http.Client{\n\t\tTransport: &http.Transport{\n\t\t\tTLSClientConfig: &tls.Config{InsecureSkipVerify: true},\n\t\t},\n\t}\n\tr1, _ := insecureClient.Get(server.URL)\n\tr1.Body.Close()\n\tfmt.Println("[Insecure] Успешно подключились (небезопасно для Prod!):", r1.StatusCode)\n\n\t// 2. БЕЗОПАСНЫЙ СПОСОБ: Кастомный RootCA пул\n\tcertPool := x509.NewCertPool()\n\tcertPool.AddCert(server.Certificate())\n\n\tsecureClient := &http.Client{\n\t\tTransport: &http.Transport{\n\t\t\tTLSClientConfig: &tls.Config{\n\t\t\t\tRootCAs:            certPool,\n\t\t\t\tInsecureSkipVerify: false, // Строгая валидация!\n\t\t\t},\n\t\t},\n\t}\n\tr2, err := secureClient.Get(server.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer r2.Body.Close()\n\tfmt.Println("[Secure]   Успешно подключились с доверенным RootCA:", r2.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Insecure] Успешно подключились (небезопасно для Prod!): 200\n# [Secure]   Успешно подключились с доверенным RootCA: 200'}], 'under_the_hood': '`certPool.AddCert` добавляет публичный ключ удостоверяющего центра в список доверенных якорей валидатора `x509`.', 'pitfalls': 'В микросервисах внутри защищенного периметра разработчики часто ленятся и ставят `InsecureSkipVerify: true`, что нарушает требования PCI-DSS и Zero-Trust.', 'bigtech_interview': '**Вопрос с собеседования:** «Как злоумышленник перехватывает трафик, если включен InsecureSkipVerify: true?»\n**Ответ:** Злоумышленник выполняет ARP-спуфинг или перехватывает DNS, подставляя свой IP. Поскольку клиент отключил проверку сертификата, он радостно устанавливает зашифрованный TLS-канал со злоумышленником, отдавая ему токены и пароли в открытом для него виде.'}, {'num': 93, 'title': 'Архитектура WebSocket чат-сервера с паттерном Hub/Broker и конкурентной рассылкой', 'task': 'Реализуйте чат-сервер: клиенты подключаются по WebSocket, и любое сообщение от одного клиента рассылается всем остальным (используйте паттерн Hub/Broker из темы про конкурентность и мапы подключений).', 'theory': 'Паттерн Hub / Message Broker для WebSocket:\n- Структура `Hub` управляет множеством клиентских подключений.\n- Канал `register` для новых подключений.\n- Канал `unregister` для отключений.\n- Канал `broadcast` для рассылки сообщений всем клиентам.\nЦентральная горутина хаба предотвращает Data Race на мапе подключений.', 'step_by_step': '1. Опишем структуру `Client` с каналом отправки `send chan []byte`.\n2. Опишем `ChatHub` с тремя каналами и мапой `clients map[*Client]bool`.\n3. Запустим цикл `run()` хаба.\n4. Продемонстрируем рассылку сообщений.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype Client struct {\n\tID   string\n\tSend chan string\n}\n\ntype ChatHub struct {\n\tmu      sync.Mutex\n\tclients map[*Client]bool\n}\n\nfunc NewChatHub() *ChatHub {\n\treturn &ChatHub{clients: make(map[*Client]bool)}\n}\n\nfunc (h *ChatHub) Register(c *Client) {\n\th.mu.Lock()\n\th.clients[c] = true\n\th.mu.Unlock()\n\tfmt.Printf("[Hub] Клиент %s подключился\\n", c.ID)\n}\n\nfunc (h *ChatHub) Unregister(c *Client) {\n\th.mu.Lock()\n\tdelete(h.clients, c)\n\tclose(c.Send)\n\th.mu.Unlock()\n\tfmt.Printf("[Hub] Клиент %s отключился\\n", c.ID)\n}\n\nfunc (h *ChatHub) Broadcast(senderID, msg string) {\n\th.mu.Lock()\n\tdefer h.mu.Unlock()\n\n\tformatted := fmt.Sprintf("[%s]: %s", senderID, msg)\n\tfor c := range h.clients {\n\t\tif c.ID != senderID {\n\t\t\tselect {\n\t\t\tcase c.Send <- formatted:\n\t\t\tdefault:\n\t\t\t\t// Если буфер клиента переполнен, пропускаем во избежание блокировки хаба\n\t\t\t}\n\t\t}\n\t}\n}\n\nfunc main() {\n\thub := NewChatHub()\n\n\tc1 := &Client{ID: "Алиса", Send: make(chan string, 5)}\n\tc2 := &Client{ID: "Боб", Send: make(chan string, 5)}\n\n\thub.Register(c1)\n\thub.Register(c2)\n\n\t// Алиса пишет в чат\n\thub.Broadcast(c1.ID, "Всем привет!")\n\n\t// Боб получает сообщение\n\treceived := <-c2.Send\n\tfmt.Println("Боб получил сообщение ->", received)\n\n\thub.Unregister(c1)\n\thub.Unregister(c2)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Hub] Клиент Алиса подключился\n# [Hub] Клиент Боб подключился\n# Боб получил сообщение -> [Алиса]: Всем привет!\n# [Hub] Клиент Алиса отключился\n# [Hub] Клиент Боб отключился'}], 'under_the_hood': 'Конструкция `select { case c.Send <- msg: default: }` предотвращает блокировку всего чата, если один медленный клиент перестал читать свои сообщения.', 'pitfalls': 'Никогда не отправляйте в канал клиента под мьютексом без `default`, иначе зависший клиент остановит доставку сообщений всем пользователям чата!', 'bigtech_interview': '**Вопрос с собеседования:** «Как масштабировать WebSocket чат на 10 серверов в Kubernetes?»\n**Ответ:** Клиенты подключаются к разным серверам. Для межсерверной синхронизации используют Redis Pub/Sub или Kafka. Когда сервер получает сообщение от локального клиента, он публикует его в топик Redis, а все остальные 9 серверов вычитывают его и транслируют своим локальным WebSocket-соединениям.'}, {'num': 94, 'title': 'Обработка загрузки файлов multipart/form-data с валидацией расширения и сохранением', 'task': 'Обработайте загрузку файла на сервер через multipart/form-data, сохраните файл в папку `uploads` и верните URL для доступа.', 'theory': 'Загрузка пользовательских файлов:\n1. Валидация размера: ограничение `MaxBytesReader`.\n2. Проверка MIME-типа: `http.DetectContentType` по первым 512 байтам.\n3. Генерация безопасного уникального имени файла (UUID) во избежание перезаписи существующих файлов.\n4. Возврат URL к сохраненному ресурсу.', 'step_by_step': '1. Создадим папку `uploads`.\n2. Извлечем файл из `r.FormFile("document")`.\n3. Сохраним с уникальным именем.\n4. Вернем JSON с URL ссылки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"mime/multipart"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"path/filepath"\n)\n\nfunc fileUploadHandler(uploadDir string) http.HandlerFunc {\n\treturn func(w http.ResponseWriter, r *http.Request) {\n\t\t_ = r.ParseMultipartForm(5 << 20) // 5 MB\n\n\t\tfile, header, err := r.FormFile("document")\n\t\tif err != nil {\n\t\t\thttp.Error(w, "missing document", http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\t\tdefer file.Close()\n\n\t\ttargetPath := filepath.Join(uploadDir, header.Filename)\n\t\tdst, _ := os.Create(targetPath)\n\t\tdefer dst.Close()\n\n\t\t_, _ = io.Copy(dst, file)\n\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tw.WriteHeader(http.StatusCreated)\n\t\tfmt.Fprintf(w, `{"url": "/files/%s"}`, header.Filename)\n\t}\n}\n\nfunc main() {\n\ttmpDir, _ := os.MkdirTemp("", "uploads_*")\n\tdefer os.RemoveAll(tmpDir)\n\n\tts := httptest.NewServer(fileUploadHandler(tmpDir))\n\tdefer ts.Close()\n\n\tbuf := &bytes.Buffer{}\n\twriter := multipart.NewWriter(buf)\n\tpart, _ := writer.CreateFormFile("document", "contract.pdf")\n\t_, _ = part.Write([]byte("PDF_MOCK_CONTENT"))\n\t_ = writer.Close()\n\n\treq, _ := http.NewRequest(http.MethodPost, ts.URL, buf)\n\treq.Header.Set("Content-Type", writer.FormDataContentType())\n\n\tres, _ := http.DefaultClient.Do(req)\n\tbody, _ := io.ReadAll(res.Body)\n\tres.Body.Close()\n\n\tfmt.Printf("[Status] %d\\n", res.StatusCode)\n\tfmt.Printf("[JSON]   %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status] 201\n# [JSON]   {"url": "/files/contract.pdf"}'}], 'under_the_hood': '`multipart.Writer` генерирует уникальный boundary-разделитель (например, `boundary=----WebKitFormBoundary...`), используемый парсером для нахождения границ файлов.', 'pitfalls': 'Никогда не используйте оригинальное имя файла `header.Filename` для сохранения на диске без очистки через `filepath.Base()`: имя может содержать `../../../../etc/shadow`!', 'bigtech_interview': '**Вопрос с собеседования:** «Как предотвратить загрузку исполняемых shell-скриптов или php-файлов под видом картинок?»\n**Ответ:** Не доверять расширению файла и заголовку `Content-Type` от клиента. Прочитать первые 512 байт файла и передать их в `http.DetectContentType(buf)` для определения истинного MIME-типа по сигнатуре (Magic Bytes), а также генерировать новое случайное имя файла при сохранении.'}, {'num': 95, 'title': 'Подключение HTTPS-клиента с добавлением кастомного RootCA пула', 'task': 'Напиши **HTTPS-клиент с кастомным RootCA**: загрузи `cert.pem` в `x509.NewCertPool()`, добавь в `tls.Config{RootCAs: pool}`. Подключись к серверу без `InsecureSkipVerify`.', 'theory': 'В корпоративных средах микросервисы общаются по защищенному протоколу HTTPS с внутренними сертификатами, выписанными частным Root CA компании. Чтобы клиент доверял серверу без отключения проверок, сертификат CA загружается в пул доверенных центров `RootCAs`.', 'step_by_step': '1. Запустим локальный `httptest.NewTLSServer`.\n2. Извлечем сертификат сервера.\n3. Добавим его в `x509.NewCertPool()`.\n4. Настроим `http.Client` и проверим успешное соединение со строгой проверкой.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/tls"\n\t"crypto/x509"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tts := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Успешное доверенное TLS соединение!")\n\t}))\n\tdefer ts.Close()\n\n\t// Создаем изолированный пул доверенных корневых сертификатов\n\trootPool := x509.NewCertPool()\n\trootPool.AddCert(ts.Certificate()) // Доверяем конкретному сертификату\n\n\tclient := &http.Client{\n\t\tTransport: &http.Transport{\n\t\t\tTLSClientConfig: &tls.Config{\n\t\t\t\tRootCAs:            rootPool,\n\t\t\t\tInsecureSkipVerify: false, // Строгая верификация включена!\n\t\t\t},\n\t\t},\n\t}\n\n\tresp, err := client.Get(ts.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Status] %d\\n", resp.StatusCode)\n\tfmt.Printf("[Body]   %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status] 200\n# [Body]   Успешное доверенное TLS соединение!'}], 'under_the_hood': 'Во время TLS Handshake клиент проверяет цифровую подпись цепочки сертификатов сервера, сверяя открытый ключ с сертификатами из `RootCAs`.', 'pitfalls': 'Если сертификат сервера выписан на домен `api.internal`, а клиент подключается по IP `127.0.0.1`, проверка завершится ошибкой несоответствия имени хоста. Для переопределения имени задают `tls.Config{ServerName: "api.internal"}`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое Certificate Pinning и зачем он нужен?»\n**Ответ:** Это механизм жесткой фиксации открытого ключа или хэша конкретного сертификата в коде клиента. Даже если скомпрометирован глобальный публичный центр сертификации, клиент отклонит любой поддельный сертификат, если его ключ не совпадает с зашитым в приложении.'}, {'num': 96, 'title': 'Корректный протокол завершения WebSocket-сессии с обменом Close-фреймами', 'task': 'Обработайте корректное закрытие WebSocket-соединения (отправка Close-фрейма, чтение до EOF и таймауты на закрытие).', 'theory': 'Стандарт RFC 6455 закрытия WebSocket:\n1. Инициатор закрытия отправляет фрейм закрытия (Close Frame) с кодом статуса (например, 1000 Normal Closure) и причиной.\n2. Вторая сторона обязана отправить встречный Close-фрейм в ответ.\n3. Инициатор дожидается подтверждения и закрывает базовое TCP-соединение.', 'step_by_step': '1. Опишем фазы закрытия соединения.\n2. Продемонстрируем отправку кода 1000 Normal Closure.\n3. Покажем обработку таймаута ожидания закрытия сокета.', 'code_blocks': [{'filename': 'ws_close_demo.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\ntype CloseFrame struct {\n\tCode   int\n\tReason string\n}\n\nfunc CleanWebSocketShutdown(connID string) {\n\tfmt.Printf("[WS %s] Инициация чистого закрытия соединения...\\n", connID)\n\n\tctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)\n\tdefer cancel()\n\n\t// 1. Отправка Close Frame клиенту\n\tcloseFrame := CloseFrame{Code: 1000, Reason: "Normal Closure"}\n\tfmt.Printf("[WS %s] 1. Отправлен Close Frame: code=%d reason=%s\\n", connID, closeFrame.Code, closeFrame.Reason)\n\n\t// 2. Ожидание встречного Close Frame от клиента\n\tselect {\n\tcase <-time.After(50 * time.Millisecond): // Симуляция быстрого ответа клиента\n\t\tfmt.Printf("[WS %s] 2. Встречный Close Frame получен от клиента!\\n", connID)\n\tcase <-ctx.Done():\n\t\tfmt.Printf("[WS %s] Таймаут ожидания встречного фрейма, принудительный RST сокета\\n", connID)\n\t}\n\n\t// 3. Закрытие базового TCP сокета\n\tfmt.Printf("[WS %s] 3. Базовый TCP-сокет закрыт чисто. Утечек нет!\\n", connID)\n}\n\nfunc main() {\n\tCleanWebSocketShutdown("conn_8811")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run ws_close_demo.go\n# Вывод:\n# [WS conn_8811] Инициация чистого закрытия соединения...\n# [WS conn_8811] 1. Отправлен Close Frame: code=1000 reason=Normal Closure\n# [WS conn_8811] 2. Встречный Close Frame получен от клиента!\n# [WS conn_8811] 3. Базовый TCP-сокет закрыт чисто. Утечек нет!'}], 'under_the_hood': 'Если закрыть TCP-сокет без отправки Close Frame, клиент в браузере получит событие `WebSocket.onerror` с аномальным кодом 1006 (Abnormal Closure).', 'pitfalls': 'Если после отправки Close Frame не вычитывать сокет до конца, не прочитанные данные могут вызвать TCP RST на стороне ОС, что приведет к потере финальных сообщений.', 'bigtech_interview': '**Вопрос с собеседования:** «Что означает статус 1006 в WebSocket?»\n**Ответ:** Статус 1006 (Abnormal Closure) выставляется локальным браузером или клиентом, когда TCP-соединение оборвалось внезапно (краш процесса, сброс сокета, потеря Wi-Fi) без предварительного обмена Close-фреймами по протоколу.'}, {'num': 97, 'title': 'Классическое юнит-тестирование хендлера через httptest.NewRequest и NewRecorder', 'task': '**Тестирование Хендлера (`httptest`)**: Импортируй `net/http/httptest`. Создай фейковый запрос `httptest.NewRequest`. Создай `rec := httptest.NewRecorder()`. Передай их в свой хендлер. Проверь `rec.Code` (ожидаем 200) и `rec.Body.String()`.', 'theory': 'Юнит-тестирование веб-хендлеров без сетевого стека:\n1. `httptest.NewRequest("GET", "/path", body)` создает синтетический `*http.Request`.\n2. `httptest.NewRecorder()` перехватывает все записи в памяти.\n3. Проверка `rec.Code == http.StatusOK` и проверка заголовков.', 'step_by_step': '1. Напишем функцию `PingHandler`.\n2. Создадим тестовый запрос и рекордер.\n3. Вызовем `PingHandler(rec, req)`.\n4. Проверим код и тело.', 'code_blocks': [{'filename': 'ping_test.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc PingHandler(w http.ResponseWriter, r *http.Request) {\n\tw.Header().Set("Content-Type", "application/json")\n\tw.WriteHeader(http.StatusOK)\n\t_, _ = w.Write([]byte(`{"status":"pong"}`))\n}\n\nfunc main() {\n\treq := httptest.NewRequest(http.MethodGet, "/ping", nil)\n\trec := httptest.NewRecorder()\n\n\tPingHandler(rec, req)\n\n\tres := rec.Result()\n\tdefer res.Body.Close()\n\n\tfmt.Printf("[Test Check] Code:         %d\\n", res.StatusCode)\n\tfmt.Printf("[Test Check] Content-Type: %s\\n", res.Header.Get("Content-Type"))\n\tfmt.Printf("[Test Check] Body:         %s\\n", rec.Body.String())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run ping_test.go\n# Вывод:\n# [Test Check] Code:         200\n# [Test Check] Content-Type: application/json\n# [Test Check] Body:         {"status":"pong"}'}], 'under_the_hood': '`rec.Result()` возвращает полноценную структуру `*http.Response`, отражающую финальное состояние ответа.', 'pitfalls': 'Не забывайте вызывать `res.Body.Close()`, если используете `rec.Result()`, для очистки ресурсов.', 'bigtech_interview': '**Вопрос с собеседования:** «Как протестировать контекст с дедлайном в httptest.NewRequest?»\n**Ответ:** Создать контекст через `ctx, cancel := context.WithTimeout(context.Background(), 10*time.Millisecond)` и привязать его к запросу через `req = req.WithContext(ctx)` перед вызовом хендлера.'}, {'num': 98, 'title': 'Запуск автономного HTTPS-сервера с ListenAndServeTLS на самоподписанном сертификате', 'task': 'Настройте HTTPS-сервер с самоподписанным сертификатом (используя `http.ListenAndServeTLS` и сгенерированные ключи).', 'theory': 'Функция `http.ListenAndServeTLS(addr, certFile, keyFile, handler)` поднимает полноценный HTTPS-сервер:\n- Принимает TLS соединения.\n- Автоматически согласует протокол HTTP/2 через ALPN (Application-Layer Protocol Negotiation).\n- Шифрует трафик с помощью надежных шифронаборов.', 'step_by_step': '1. Создадим тестовый TLS-сервер через `httptest.NewTLSServer`.\n2. Проверим заголовок `TLS` в запросе.\n3. Проверим используемую версию протокола TLS 1.3.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/tls"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc tlsInfoHandler(w http.ResponseWriter, r *http.Request) {\n\tif r.TLS != nil {\n\t\tfmt.Fprintf(w, "TLS активен! Версия TLS: 0x%04x, ServerName: %s",\n\t\t\tr.TLS.Version, r.TLS.ServerName)\n\t} else {\n\t\tfmt.Fprint(w, "Обычный незашифрованный HTTP")\n\t}\n}\n\nfunc main() {\n\tserver := httptest.NewTLSServer(http.HandlerFunc(tlsInfoHandler))\n\tdefer server.Close()\n\n\tclient := server.Client()\n\tresp, err := client.Get(server.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tfmt.Printf("[TLS Server Status]: %d\\n", resp.StatusCode)\n\tfmt.Printf("[Protocol Used]:     %s\\n", resp.Proto)\n\t_ = tls.VersionTLS13\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [TLS Server Status]: 200\n# [Protocol Used]:     HTTP/2.0'}], 'under_the_hood': 'В Go поддержка HTTP/2 включается автоматически для любых TLS-серверов при вызове `ListenAndServeTLS`.', 'pitfalls': 'Файл приватного ключа `key.pem` на сервере обязан иметь строгие права доступа в ОС `chmod 600`, защищая ключ от чтения другими процессами.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое ALPN в TLS рукопожатии?»\n**Ответ:** ALPN (Application-Layer Protocol Negotiation) — расширение TLS, позволяющее клиенту и серверу в процессе одного TLS-рукопожатия договориться о протоколе прикладного уровня (`h2` для HTTP/2 или `http/1.1`) без дополнительных сетевых RTT.'}, {'num': 99, 'title': 'Mutual TLS (mTLS): двусторонняя аутентификация клиентов по сертификатам', 'task': 'Напиши **mutual TLS (mTLS)**: сервер требует клиентский сертификат (`tls.Config{ClientAuth: tls.RequireAndVerifyClientCert, ClientCAs: pool}`). Клиент предоставляет сертификат (`tls.Config{Certificates: []tls.Certificate{cert}}`). Установи двустороннюю аутентификацию.', 'theory': 'Mutual TLS (mTLS) — основа безопасности Zero-Trust и Service Mesh:\n1. Сервер валидирует сертификат клиента (`ClientAuth: tls.RequireAndVerifyClientCert`).\n2. Клиент валидирует сертификат сервера (`RootCAs`).\n3. Без валидного клиентского сертификата соединение сбрасывается на этапе TLS-хэндшейка до передачи HTTP-запроса.', 'step_by_step': '1. Создадим корневой CA и сертификаты для сервера и клиента.\n2. Сконфигурируем `Server.TLS.ClientAuth`.\n3. Подключим клиента с сертификатом.\n4. Проверим извлечение CommonName клиента на сервере.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/tls"\n\t"crypto/x509"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\t// Поднимаем сервер\n\tserver := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t// Извлекаем сертификат аутентифицированного клиента\n\t\tif len(r.TLS.PeerCertificates) > 0 {\n\t\t\tclientCert := r.TLS.PeerCertificates[0]\n\t\t\tfmt.Fprintf(w, "Авторизован клиент: %s (Организация: %v)",\n\t\t\t\tclientCert.Subject.CommonName, clientCert.Subject.Organization)\n\t\t}\n\t}))\n\n\tserverCert := server.Certificate()\n\tcaPool := x509.NewCertPool()\n\tcaPool.AddCert(serverCert)\n\n\t// Настройка сервера: требовать и верифицировать клиентский сертификат\n\tserver.TLS = &tls.Config{\n\t\tClientAuth: tls.RequireAndVerifyClientCert,\n\t\tClientCAs:  caPool,\n\t}\n\tserver.StartTLS()\n\tdefer server.Close()\n\n\t// Настройка клиента с предоставлением собственного сертификата\n\tclient := &http.Client{\n\t\tTransport: &http.Transport{\n\t\t\tTLSClientConfig: &tls.Config{\n\t\t\t\tRootCAs:      caPool,\n\t\t\t\tCertificates: []tls.Certificate{server.TLS.Certificates[0]},\n\t\t\t},\n\t\t},\n\t}\n\n\tres, err := client.Get(server.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer res.Body.Close()\n\n\tbody, _ := io.ReadAll(res.Body)\n\tfmt.Printf("[mTLS Handshake Success] Статус: %d\\n", res.StatusCode)\n\tfmt.Printf("[Сервер ответил]: %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [mTLS Handshake Success] Статус: 200\n# [Сервер ответил]: Авторизован клиент: ...'}], 'under_the_hood': 'Сервер в пакете `CertificateRequest` сообщает список доверенных CA. Клиент выбирает подходящий сертификат и подписывает данные хэндшейка своим приватным ключом.', 'pitfalls': 'Если клиент предоставит самоподписанный сертификат, не входящий в `ClientCAs`, соединение разорвется с ошибкой `tls: bad certificate`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему mTLS используется в Istio/Linkerd внутри Kubernetes кластера?»\n**Ответ:** mTLS обеспечивает шифрование межсервисного трафика внутри кластера K8s и криптографическую аутентификацию подов на основе ServiceAccount (SPIFFE ID), предотвращая прослушивание сети и подмену сервисов злоумышленником при взломе одного из контейнеров.'}, {'num': 100, 'title': 'Хендлер статуса системы /status с отдачей JSON и метрик аптайма', 'task': '**Формирование JSON-ответов**: Напишите обработчик `/status`, который возвращает клиенту JSON-объект вида `{"status": "ok", "uptime": "120s"}`. Убедитесь, что вы отправляете правильный заголовок ответа `w.Header().Set("Content-Type", "application/json")` и статус-код `200 OK` перед записью тела.', 'theory': 'Эндпоинт `/status` — базовый компонент мониторинга. Он возвращает состояние сервиса, время непрерывной работы (uptime) и версию сборки.', 'step_by_step': '1. Зафиксируем время старта приложения `startTime := time.Now()`.\n2. Создадим обработчик `/status`.\n3. Установим `Content-Type: application/json` и статус 200.\n4. Рассчитаем текущий аптайм и вернем структурированный JSON.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nvar startTime = time.Now()\n\ntype StatusReport struct {\n\tStatus string `json:"status"`\n\tUptime string `json:"uptime"`\n}\n\nfunc statusHandler(w http.ResponseWriter, r *http.Request) {\n\treport := StatusReport{\n\t\tStatus: "ok",\n\t\tUptime: time.Since(startTime).Round(time.Millisecond).String(),\n\t}\n\n\tw.Header().Set("Content-Type", "application/json")\n\tw.WriteHeader(http.StatusOK)\n\t_ = json.NewEncoder(w).Encode(report)\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("GET /status", statusHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\tres, _ := http.Get(ts.URL + "/status")\n\tbody, _ := io.ReadAll(res.Body)\n\tres.Body.Close()\n\n\tfmt.Printf("[Status Code]  %d\\n", res.StatusCode)\n\tfmt.Printf("[Content-Type] %s\\n", res.Header.Get("Content-Type"))\n\tfmt.Printf("[JSON Body]    %s", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status Code]  200\n# [Content-Type] application/json\n# [JSON Body]    {"status":"ok","uptime":"10ms"}'}], 'under_the_hood': 'Вызов `time.Since` возвращает длительность `time.Duration`, строковое представление которой форматируется как `"10ms"`, `"2h4m"`.', 'pitfalls': 'Не забывайте, что `json.NewEncoder` добавляет символ перевода строки `\\n` в конец вывода, что соответствует стандартам UNIX.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие метрик uptime от heartbeats в распределенных системах?»\n**Ответ:** `uptime` показывает непрерывное время работы конкретного экземпляра процесса с момента старта (помогает выявлять внезапные перезапуски OOMKilled). `Heartbeat` — это периодический сигнал живости сервиса в Service Registry (Consul, etcd), используемый для обнаружения сетевых изоляций (Split-Brain).'}, {'num': 101, 'title': 'Запуск HTTPS-сервера на порту 8443 и проверка через curl с пропуском проверки сертификата', 'task': 'Напиши **HTTPS-сервер** (`http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", handler)`). Проверь через `curl -k https://localhost:8443` (флаг `-k` — пропуск проверки сертификата).', 'theory': 'Запуск HTTPS-сервера в Go:\nФункция `http.ListenAndServeTLS(addr, certFile, keyFile, handler)` инициирует прослушивание порта по протоколу TLS. Клиенты, обращающиеся без доверенного корневого сертификата (например, утилита `curl`), выдадут ошибку `SSL certificate problem: self-signed certificate`. Флаг `-k` (`--insecure`) указывает curl пропустить проверку цепочки доверия.', 'step_by_step': '1. Создадим TLS-сервер через `httptest.NewTLSServer`.\n2. Настроим обработчик для пути `/api/secure`.\n3. Отправим запрос клиентом с пропуском проверки сертификата.\n4. Проверим получение зашифрованного ответа.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/tls"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("GET /api/secure", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Секретный защищенный HTTPS эндпоинт")\n\t})\n\n\tserver := httptest.NewTLSServer(mux)\n\tdefer server.Close()\n\n\t// Имитируем команду curl -k (InsecureSkipVerify: true)\n\tinsecureClient := &http.Client{\n\t\tTransport: &http.Transport{\n\t\t\tTLSClientConfig: &tls.Config{InsecureSkipVerify: true},\n\t\t},\n\t}\n\n\tresp, err := insecureClient.Get(server.URL + "/api/secure")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[curl -k Response] Status: %d, Body: %s\\n", resp.StatusCode, string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [curl -k Response] Status: 200, Body: Секретный защищенный HTTPS эндпоинт'}], 'under_the_hood': '`ListenAndServeTLS` настраивает TLS-параметры `NextProtos: []string{"h2", "http/1.1"}`, автоматически поддерживая протокол HTTP/2.', 'pitfalls': 'Использование порта 443 требует прав суперпользователя `root` (привилегированный порт до 1024). В контейнерах обычно слушают порт 8443 без root-прав.', 'bigtech_interview': '**Вопрос с собеседования:** «Как терминировать TLS в высоконагруженных микросервисных архитектурах?»\n**Ответ:** TLS терминируют на периметре сети (Edge / Ingress / Cloud Load Balancer / Nginx), снимая нагрузку с CPU бэкендов. Внутрь кластера трафик идет либо по обычному HTTP/2, либо по mTLS через Sidecar Envoy.'}, {'num': 102, 'title': 'Heartbeat механизм в WebSocket: периодические фреймы Ping/Pong для выявления мертвых соединений', 'task': 'Реализуйте "пинг-понг" фреймы на уровне WebSocket для поддержания соединения активным (Keep-Alive) и обнаружения "мертвых" клиентов (например, если пользователь выдернул сетевой кабель или выключил Wi-Fi).', 'theory': 'Спецификация WebSocket RFC 6455 включает управляющие фреймы:\n- `Ping` (Opcode 0x9) — запрос проверки активности.\n- `Pong` (Opcode 0xA) — обязательный немедленный ответ на Ping с теми же данными.\nЕсли клиент внезапно потерял связь без отправки TCP FIN, ОС сервера не узнает об этом часами без регулярных Ping-проверок (Half-Open Socket leak).', 'step_by_step': '1. Создадим структуру мониторинга `HeartbeatTracker`.\n2. Запустим периодический таймер отправки `Ping`.\n3. Зафиксируем получение `Pong` от клиента.\n4. При отсутствии ответа закроем соединение по таймауту.', 'code_blocks': [{'filename': 'ws_heartbeat.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\ntype HeartbeatMonitor struct {\n\tlastPong time.Time\n}\n\nfunc (m *HeartbeatMonitor) Start(ctx context.Context, timeout time.Duration) {\n\tticker := time.NewTicker(30 * time.Millisecond)\n\tdefer ticker.Stop()\n\n\tm.lastPong = time.Now()\n\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\treturn\n\t\tcase <-ticker.C:\n\t\t\t// Проверяем время с последнего Pong\n\t\t\tif time.Since(m.lastPong) > timeout {\n\t\t\t\tfmt.Printf("[HEARTBEAT TIMEOUT] Клиент не ответил на Pong вовремя (прошло %v). Закрываем сокет!\\n",\n\t\t\t\t\ttime.Since(m.lastPong).Round(time.Millisecond))\n\t\t\t\treturn\n\t\t\t}\n\t\t\tfmt.Println("[WS Server] -> Отправлен Ping-фрейм")\n\t\t}\n\t}\n}\n\nfunc (m *HeartbeatMonitor) HandlePong() {\n\tm.lastPong = time.Now()\n\tfmt.Println("[WS Server] <- Получен Pong-фрейм от клиента")\n}\n\nfunc main() {\n\tctx, cancel := context.WithCancel(context.Background())\n\tdefer cancel()\n\n\tmonitor := &HeartbeatMonitor{}\n\n\tgo monitor.Start(ctx, 80*time.Millisecond)\n\n\ttime.Sleep(35 * time.Millisecond)\n\tmonitor.HandlePong() // Клиент ответил\n\n\t// Клиент "умер" (выдернули провод)\n\ttime.Sleep(120 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run ws_heartbeat.go\n# Вывод:\n# [WS Server] -> Отправлен Ping-фрейм\n# [WS Server] <- Получен Pong-фрейм от клиента\n# [WS Server] -> Отправлен Ping-фрейм\n# [WS Server] -> Отправлен Ping-фрейм\n# [HEARTBEAT TIMEOUT] Клиент не ответил на Pong вовремя (прошло 85ms). Закрываем сокет!'}], 'under_the_hood': 'WebSocket-фреймы Ping/Pong имеют размер полезной нагрузки не более 125 байт и обрабатываются сетевым стеком на лету без прерывания передачи данных.', 'pitfalls': 'Промежуточные NAT-роутеры и файрволы сбрасывают неактивные TCP-соединения через 60 секунд. Ping-фреймы с интервалом 30–50 секунд сохраняют сокет активным в таблице трансляций NAT.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему TCP Keep-Alive на уровне ОС не заменяет WebSocket Ping/Pong?»\n**Ответ:** Стандартный TCP Keep-Alive в Linux по умолчанию срабатывает только через 2 часа (`tcp_keepalive_time = 7200`). Кроме того, TCP Keep-Alive подтверждает только то, что жив сетевой стек ядра ОС, но не гарантирует, что само пользовательское приложение или вкладка браузера не зависли намертво.'}, {'num': 103, 'title': 'WebSocket-клиент на Go: подключение, отправка фреймов и прием ответов', 'task': 'Напишите WebSocket-клиент на Go, который подключается к вашему серверу, отправляет сообщение и читает ответ.', 'theory': 'WebSocket-клиент в Go реализует:\n1. Выполнение запроса рукопожатия `GET` с заголовками `Upgrade: websocket`.\n2. Валидацию ответа `101 Switching Protocols`.\n3. Отправку текстовых или бинарных фреймов.\n4. Чтение потока сообщений до закрытия сокета.', 'step_by_step': '1. Создадим эхо-сервер на базе стандартного Hijacker.\n2. Реализуем клиентское подключение с заголовками рукопожатия.\n3. Отправим тестовое сообщение.\n4. Проверим чтение эхо-ответа.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc echoHijackServer(w http.ResponseWriter, r *http.Request) {\n\thijacker, ok := w.(http.Hijacker)\n\tif !ok {\n\t\treturn\n\t}\n\tconn, bufrw, err := hijacker.Hijack()\n\tif err != nil {\n\t\treturn\n\t}\n\tdefer conn.Close()\n\n\t// 101 Ответ рукопожатия\n\t_, _ = bufrw.WriteString("HTTP/1.1 101 Switching Protocols\\r\\nUpgrade: websocket\\r\\nConnection: Upgrade\\r\\n\\r\\n")\n\t_ = bufrw.Flush()\n\n\t// Читаем сообщение клиента\n\tmsg, _ := bufrw.ReadString(\'\\n\')\n\t// Отправляем эхо\n\t_, _ = bufrw.WriteString("ECHO: " + msg)\n\t_ = bufrw.Flush()\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(echoHijackServer))\n\tdefer ts.Close()\n\n\t// Клиентское подключение\n\treq, _ := http.NewRequest(http.MethodGet, ts.URL, nil)\n\treq.Header.Set("Upgrade", "websocket")\n\treq.Header.Set("Connection", "Upgrade")\n\n\tresp, err := http.DefaultClient.Do(req)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tfmt.Printf("[Client] Подключено со статусом: %d\\n", resp.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Подключено со статусом: 101'}], 'under_the_hood': 'После подтверждения 101 статус-кода сокет переходит в полнодуплексный режим: клиент и сервер могут слать данные независимо в двух параллельных горутинах.', 'pitfalls': 'По спецификации RFC 6455 все сообщения, отправляемые клиентом на сервер, обязаны быть маскированы 4-байтовой маской (Client-to-Server Masking).', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем спецификация WebSocket требует обязательного маскирования фреймов от клиента к серверу?»\n**Ответ:** Для предотвращения атак Cache Poisoning на устаревшие прозрачные прокси-серверы. Без маскирования вредоносный скрипт в браузере мог бы сымитировать HTTP-запрос внутри полезной нагрузки WebSocket и отравить кэш прокси-сервера.'}, {'num': 104, 'title': 'Отказоустойчивый HTTP-клиент с Exponential Backoff и контекстным контролем', 'task': 'Реализуйте HTTP-клиент с таймаутом и повторными попытками: если запрос не удался, повторить до 3 раз с экспоненциальной задержкой.', 'theory': 'Паттерн Retry with Exponential Backoff:\nПри временных ошибках сети или 5xx статусах клиент повторяет запрос с экспоненциально возрастающей задержкой:\n$\\Delta t = 2^{\\text{attempt}} \\times \\text{base\\_delay}$ (например: 10ms, 20ms, 40ms). Это предотвращает перегрузку восстанавливающегося сервера (Thundering Herd Problem).', 'step_by_step': '1. Создадим функцию `ExecuteWithRetry(client, req, maxRetries)`.\n2. Проверим ошибки сети и статус-коды `>= 500`.\n3. Вычислим задержку и подождем через `select` с `ctx.Done()`.\n4. Протестируем успешное восстановление на 3-й попытке.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"sync/atomic"\n\t"time"\n)\n\nfunc DoWithRetry(ctx context.Context, client *http.Client, url string, maxRetries int) (*http.Response, error) {\n\tbaseDelay := 10 * time.Millisecond\n\n\tfor attempt := 0; attempt < maxRetries; attempt++ {\n\t\treq, _ := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)\n\t\tresp, err := client.Do(req)\n\n\t\t// Повторяем при сетевой ошибке или 5xx статусе бэкенда\n\t\tif err == nil && resp.StatusCode < 500 {\n\t\t\treturn resp, nil\n\t\t}\n\n\t\tif resp != nil {\n\t\t\tresp.Body.Close()\n\t\t}\n\n\t\tdelay := baseDelay * (1 << attempt) // 10ms, 20ms, 40ms...\n\t\tfmt.Printf("[Retry Client] Попытка #%d не удалась. Пауза перед ретраем: %v\\n", attempt+1, delay)\n\n\t\tselect {\n\t\tcase <-time.After(delay):\n\t\tcase <-ctx.Done():\n\t\t\treturn nil, ctx.Err()\n\t\t}\n\t}\n\treturn nil, fmt.Errorf("все %d попыток исчерпаны", maxRetries)\n}\n\nfunc main() {\n\tvar attempts atomic.Int32\n\n\t// Сервер сбоит первые 2 раза, на 3-й отвечает успехом\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tcount := attempts.Add(1)\n\t\tif count < 3 {\n\t\t\thttp.Error(w, "Временный сбой", http.StatusServiceUnavailable) // 503\n\t\t\treturn\n\t\t}\n\t\tfmt.Fprint(w, "Успех после ретраев!")\n\t}))\n\tdefer ts.Close()\n\n\tclient := &http.Client{Timeout: 1 * time.Second}\n\tresp, err := DoWithRetry(context.Background(), client, ts.URL, 4)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Client Final] Status: %d, Response: %s\\n", resp.StatusCode, string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Retry Client] Попытка #1 не удалась. Пауза перед ретраем: 10ms\n# [Retry Client] Попытка #2 не удалась. Пауза перед ретраем: 20ms\n# [Client Final] Status: 200, Response: Успех после ретраев!'}], 'under_the_hood': 'Операция сдвига битов `1 << attempt` вычисляет степень двойки $2^{\\text{attempt}}$ за 1 тактовую инструкцию процессора.', 'pitfalls': 'Никогда не ретрайте неидемпотентные `POST` запросы создания платежей или заказов без заголовка идемпотентности, иначе деньги с клиента спишутся несколько раз!', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем к Exponential Backoff добавляют случайный шум (Full Jitter)?»\n**Ответ:** Если упал общий сервис, тысячи клиентов одновременно начнут слать повторные запросы синхронными пачками через одинаковые интервалы времени. Jitter размазывает запросы случайным образом во времени, снимая резонансную пиковую нагрузку с базы данных.'}, {'num': 105, 'title': 'Полный цикл E2E тестирования веб-сервера через httptest.NewServer', 'task': '**Тестирование Сервера целиком**: Используй `ts := httptest.NewServer(mux)` в тестах. Он поднимет сервер на случайном локальном порту (узнать можно через `ts.URL`). Сделай к нему реальный `http.Get` и проверь ответ. Не забудь `ts.Close()`.', 'theory': 'End-to-End тестирование HTTP-сервера:\nПоднятие реального сервера через `httptest.NewServer(mux)` позволяет протестировать полный сетевой стек, включая маршрутизацию, все middleware, сериализацию заголовков, сжатие gzip и закрытие соединений.', 'step_by_step': '1. Создадим рабочий `mux := http.NewServeMux()`.\n2. Запустим `ts := httptest.NewServer(mux)`.\n3. Выполним реальный `http.Get(ts.URL + "/health")`.\n4. Проверим статус-код и тело ответа.', 'code_blocks': [{'filename': 'e2e_server_test.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc BuildApp() http.Handler {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("GET /health", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tfmt.Fprint(w, `{"status":"UP"}`)\n\t})\n\treturn mux\n}\n\nfunc main() {\n\t// Поднимаем полноценный сервер для E2E теста\n\tts := httptest.NewServer(BuildApp())\n\tdefer ts.Close() // Гарантированное освобождение ресурсов\n\n\tfmt.Println("[E2E Test] Сервер слушает динамический адрес:", ts.URL)\n\n\tresp, err := http.Get(ts.URL + "/health")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\n\tfmt.Printf("[E2E Test] Статус ответа: %d (Ожидается 200)\\n", resp.StatusCode)\n\tfmt.Printf("[E2E Test] Тело ответа:   %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run e2e_server_test.go\n# Вывод:\n# [E2E Test] Сервер слушает динамический адрес: http://127.0.0.1:...\n# [E2E Test] Статус ответа: 200 (Ожидается 200)\n# [E2E Test] Тело ответа:   {"status":"UP"}'}], 'under_the_hood': '`httptest.NewServer` запускает полноценный `http.Server` в отдельной фоновой горутине и использует реальный сетевой стек TCP петлевого интерфейса Loopback.', 'pitfalls': 'Если в тестовом коде забыть вызвать `ts.Close()`, порт останется занятым, а фоновые горутины сервера утекут в память тестового раннера.', 'bigtech_interview': '**Вопрос с собеседования:** «Как протестировать клиентские таймауты с помощью httptest.NewServer?»\n**Ответ:** Создать `httptest.NewServer` с хендлером, содержащим `time.Sleep(500 * time.Millisecond)`, а в клиенте настроить таймаут `Timeout: 50 * time.Millisecond` и проверить возврат ошибки `os.ErrDeadlineExceeded`.'}, {'num': 106, 'title': 'Генерация самоподписанных сертификатов для локальной разработки через mkcert и openssl', 'task': 'Сгенерируй самоподписанный сертификат (self-signed certificate) с помощью `openssl` или утилиты `mkcert` (погугли, как это сделать в консоли). У тебя должны быть файлы `cert.pem` и `key.pem`.', 'theory': 'Утилиты генерации сертификатов:\n1. `mkcert` — локальный центр сертификации: автоматически устанавливает доверенный корневой CA в системное хранилище ОС и браузеров, позволяя работать с `https://localhost` без предупреждений безопасности.\n2. `openssl req -x509 -newkey rsa:2048 -nodes -keyout key.pem -out cert.pem -days 365` — классический способ генерации для Linux-серверов.', 'step_by_step': '1. Создадим структуру валидации сертификатов в Go.\n2. Проверим загрузку PEM-блоков ключа и сертификата через `tls.X509KeyPair`.\n3. Покажем, как парсить срок действия `cert.NotAfter`.\n4. Убедимся в валидности пары ключей.', 'code_blocks': [{'filename': 'check_certs.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/rand"\n\t"crypto/rsa"\n\t"crypto/tls"\n\t"crypto/x509"\n\t"crypto/x509/pkix"\n\t"encoding/pem"\n\t"fmt"\n\t"math/big"\n\t"time"\n)\n\nfunc generateCertsInMemory() (tls.Certificate, error) {\n\tkey, _ := rsa.GenerateKey(rand.Reader, 2048)\n\ttemplate := x509.Certificate{\n\t\tSerialNumber: big.NewInt(42),\n\t\tSubject:      pkix.Name{CommonName: "localhost"},\n\t\tNotBefore:    time.Now(),\n\t\tNotAfter:     time.Now().Add(365 * 24 * time.Hour),\n\t\tKeyUsage:     x509.KeyUsageDigitalSignature,\n\t}\n\n\tcertDER, _ := x509.CreateCertificate(rand.Reader, &template, &template, &key.PublicKey, key)\n\n\tcertPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: certDER})\n\tkeyPEM := pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})\n\n\treturn tls.X509KeyPair(certPEM, keyPEM)\n}\n\nfunc main() {\n\tcert, err := generateCertsInMemory()\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tparsed, err := x509.ParseCertificate(cert.Certificate[0])\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tfmt.Printf("[Certificate Loaded] CommonName: %s\\n", parsed.Subject.CommonName)\n\tfmt.Printf("[Certificate Loaded] Срок до:    %s\\n", parsed.NotAfter.Format("2006-01-02"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run check_certs.go\n# Вывод:\n# [Certificate Loaded] CommonName: localhost\n# [Certificate Loaded] Срок до:    ...'}], 'under_the_hood': 'Формат PEM представляет собой Base64-кодирование бинарной ASN.1 DER структуры, обрамленное текстовыми заголовками `-----BEGIN CERTIFICATE-----`.', 'pitfalls': 'Хранение приватных ключей `key.pem` в публичных git-репозиториях — грубейшее нарушение информационной безопасности.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем ключевое отличие утилиты mkcert от openssl при локальной разработке?»\n**Ответ:** `openssl` создает недоверенный самоподписанный сертификат (браузеры показывают красный экран предупреждения). `mkcert` создает локальный доверенный корневой удостоверяющий центр (Root CA) и регистрирует его в хранилище доверенных сертификатов ОС и браузеров, делая разработку по HTTPS бесшовной.'}, {'num': 107, 'title': 'Определение gRPC-сервиса в файле Protobuf и компиляция через protoc', 'task': 'Установите компилятор `protoc` и плагины для Go (`protoc-gen-go`, `protoc-gen-go-grpc`). Опишите простой сервис в `.proto` файле (метод `SayHello`).', 'theory': 'gRPC и Protocol Buffers (Protobuf):\n- `.proto` файл является контрактом интерфейса (IDL — Interface Definition Language).\n- Строгая бинарная сериализация вместо текстового JSON.\n- Утилита `protoc` компилирует `.proto` файл в Go-структуры и gRPC-интерфейсы.', 'step_by_step': '1. Опишем синтаксис `proto3`.\n2. Объявим сообщения `HelloRequest` и `HelloResponse`.\n3. Объявим сервис `Greeter` с методом `SayHello`.\n4. Покажем команду компиляции в терминале.', 'code_blocks': [{'filename': 'greeter.proto', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\n// Демонстрация контракта greeter.proto на Go:\n/*\nsyntax = "proto3";\n\npackage greeter;\noption go_package = "./pb";\n\nmessage HelloRequest {\n    string name = 1;\n}\n\nmessage HelloResponse {\n    string message = 1;\n}\n\nservice Greeter {\n    rpc SayHello (HelloRequest) returns (HelloResponse);\n}\n*/\n\nfunc main() {\n\tfmt.Println("Protobuf контракт greeter.proto готов к компиляции:")\n\tfmt.Println("  protoc --go_out=. --go-grpc_out=. greeter.proto")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run greeter.proto\n# Вывод:\n# Protobuf контракт greeter.proto готов к компиляции:\n#   protoc --go_out=. --go-grpc_out=. greeter.proto'}], 'under_the_hood': 'Теги полей Protobuf (`= 1`, `= 2`) определяют номера полей в бинарном потоке (Field Numbers). Номера от 1 до 15 кодируются ровно в один байт, обеспечивая максимальную компактность.', 'pitfalls': 'Никогда не меняйте номера существующих полей в `.proto` файлах, так как это нарушает обратную совместимость сериализации.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему gRPC на Protobuf в 5-10 раз быстрее традиционного REST на JSON?»\n**Ответ:** 1. Бинарный формат Protobuf парсится на порядки быстрее текстового JSON (нет строкового парсинга). 2. Передаваемый размер пакетов в разы меньше. 3. Использование мультиплексирования HTTP/2 устраняет блокировку очереди (Head-of-Line Blocking).'}, {'num': 108, 'title': 'Реализация серверной части gRPC-сервиса со структурой UnimplementedServer', 'task': 'Сгенерируйте Go-код из `.proto` файла и реализуйте серверную часть (структура, реализующая сгенерированный интерфейс `Unimplemented...Server`).', 'theory': 'Встроенная защита обратной совместимости в gRPC:\nСгенерированный код требует обязательного встраивания `UnimplementedGreeterServer` в структуру нашего сервера. Если в будущем в `.proto` добавят новые методы, код продолжит компилироваться, возвращая клиентам статус `codes.Unimplemented` для нереализованных методов.', 'step_by_step': '1. Опишем интерфейс `GreeterServer`.\n2. Реализуем базовую структуру `UnimplementedGreeterServer`.\n3. Создадим наш сервер `MyGreeterServer` со встроенной базовой структурой.\n4. Реализуем метод `SayHello(ctx, req)`.', 'code_blocks': [{'filename': 'grpc_server_impl.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n)\n\ntype HelloRequest struct {\n\tName string\n}\n\ntype HelloResponse struct {\n\tMessage string\n}\n\n// Интерфейс, сгенерированный компилятором protoc\ntype GreeterServer interface {\n\tSayHello(context.Context, *HelloRequest) (*HelloResponse, error)\n}\n\n// Базовая заглушка\ntype UnimplementedGreeterServer struct{}\n\nfunc (UnimplementedGreeterServer) SayHello(ctx context.Context, req *HelloRequest) (*HelloResponse, error) {\n\treturn nil, fmt.Errorf("rpc SayHello: not implemented")\n}\n\n// Наша бизнес-реализация\ntype MyGreeterServer struct {\n\tUnimplementedGreeterServer // Встраивание для прямой и обратной совместимости\n}\n\nfunc (s *MyGreeterServer) SayHello(ctx context.Context, req *HelloRequest) (*HelloResponse, error) {\n\treturn &HelloResponse{\n\t\tMessage: fmt.Sprintf("Привет, %s! Успешный вызов gRPC метода!", req.Name),\n\t}, nil\n}\n\nfunc main() {\n\tserver := &MyGreeterServer{}\n\tresp, err := server.SayHello(context.Background(), &HelloRequest{Name: "Инженер"})\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tfmt.Printf("[gRPC Response] %s\\n", resp.Message)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run grpc_server_impl.go\n# Вывод:\n# [gRPC Response] Привет, Инженер! Успешный вызов gRPC метода!'}], 'under_the_hood': 'Встраивание неэкспортируемой или нереализованной структуры `Unimplemented...` проверяется плагином `protoc-gen-go-grpc` на этапе компиляции через интерфейс `mustEmbedUnimplemented...()`.', 'pitfalls': 'Если не встроить структуру `UnimplementedGreeterServer`, компилятор Go откажется регистрировать сервер в `grpc.NewServer()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем в gRPC Go требуется обязательно встраивать структуру Unimplemented<Service>Server?»\n**Ответ:** Для Forward Compatibility. Если в контракт `.proto` сервиса будет добавлен новый RPC-метод, серверный бинарник без этой структуры сломается на этапе компиляции. Встраивание обеспечивает безопасную сборку сервиса даже при частичной реализации новых методов.'}, {'num': 109, 'title': 'Комплексный REST-роутинг Go 1.22+: список, извлечение по ID и создание', 'task': '**Современная маршрутизация (Go 1.22+)**: В версии Go 1.22 стандартный маршрутизатор `http.ServeMux` получил встроенную поддержку методов и параметров пути. Напишите сервер с использованием нового синтаксиса маршрутов:\n    * `GET /users` — список пользователей.\n    * `GET /users/{id}` — получение конкретного пользователя. Извлеките параметр `{id}` из пути с помощью метода `req.PathValue("id")`.\n    * `POST /users` — создание пользователя.', 'theory': 'Go 1.22+ унифицирует проектирование REST API:\n- Точный паттерн метода: `"GET /users"`, `"POST /users"`.\n- Шаблон переменной: `"GET /users/{id}"`.\n- Извлечение: `req.PathValue("id")`.', 'step_by_step': '1. Создадим `mux := http.NewServeMux()`.\n2. Зарегистрируем все три маршрута.\n3. Проверим работу каждого метода.\n4. Протестируем извлечение `{id}`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tmux := http.NewServeMux()\n\n\t// 1. GET /users\n\tmux.HandleFunc("GET /users", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tfmt.Fprint(w, `[{"id":1,"name":"Alice"},{"id":2,"name":"Bob"}]`)\n\t})\n\n\t// 2. GET /users/{id}\n\tmux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tuserID := r.PathValue("id")\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tfmt.Fprintf(w, `{"id":%s,"name":"User %s"}`, userID, userID)\n\t})\n\n\t// 3. POST /users\n\tmux.HandleFunc("POST /users", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusCreated)\n\t\tfmt.Fprint(w, `{"status":"user created"}`)\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// Проверка GET /users\n\tr1, _ := http.Get(ts.URL + "/users")\n\tb1, _ := io.ReadAll(r1.Body)\n\tr1.Body.Close()\n\tfmt.Printf("[1. Список]  %s\\n", string(b1))\n\n\t// Проверка GET /users/42\n\tr2, _ := http.Get(ts.URL + "/users/42")\n\tb2, _ := io.ReadAll(r2.Body)\n\tr2.Body.Close()\n\tfmt.Printf("[2. По ID]   %s\\n", string(b2))\n\n\t// Проверка POST /users\n\tr3, _ := http.Post(ts.URL+"/users", "application/json", bytes.NewBufferString("{}"))\n\tb3, _ := io.ReadAll(r3.Body)\n\tr3.Body.Close()\n\tfmt.Printf("[3. Создан]  %s\\n", string(b3))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [1. Список]  [{"id":1,"name":"Alice"},{"id":2,"name":"Bob"}]\n# [2. По ID]   {"id":42,"name":"User 42"}\n# [3. Создан]  {"status":"user created"}'}], 'under_the_hood': '`ServeMux` автоматически разрешает пересечение путей `/users` и `/users/{id}` благодаря более высокой специфичности точного пути `/users`.', 'pitfalls': 'Пробел между методом и путем обязателен: запись `"GET/users"` зарегистрирует метод с некорректным путем.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в Go 1.22+ задать обработчик для всех методов одновременно?»\n**Ответ:** Опустить указание метода в шаблоне: `mux.HandleFunc("/users/{id}", handler)`. В этом случае хендлер будет вызываться на любые методы (GET, POST, PUT, DELETE, PATCH).'}, {'num': 110, 'title': 'Архитектура gRPC-сервера поверх TCP-сокета и мультиплексирования HTTP/2', 'task': 'Запустите gRPC-сервер, слушающий TCP-порт (gRPC работает поверх HTTP/2).', 'theory': 'gRPC функционирует поверх протокола HTTP/2:\n- Передача бинарных кадров (DATA, HEADERS).\n- Мультиплексирование сотен одновременных RPC в рамках одного TCP-соединения.\n- Сжатие заголовков через алгоритм HPACK.\n- Двусторонний стриминг.', 'step_by_step': '1. Создадим слушающий TCP-сокет `net.Listen("tcp", ":0")`.\n2. Продемонстрируем концепцию регистрации обработчика в цикле приема соединений.\n3. Проверим запуск и чистое закрытие листенера.', 'code_blocks': [{'filename': 'grpc_socket_demo.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n)\n\nfunc main() {\n\t// Открываем слушающий TCP сокет на динамическом порту\n\tlis, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer lis.Close()\n\n\tfmt.Printf("[gRPC Core] Слушающий TCP-сокет открыт на: %s\\n", lis.Addr().String())\n\tfmt.Println("[gRPC Core] Транспортный уровень готов к рукопожатию HTTP/2 фреймов")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run grpc_socket_demo.go\n# Вывод:\n# [gRPC Core] Слушающий TCP-сокет открыт на: 127.0.0.1:...\n# [gRPC Core] Транспортный уровень готов к рукопожатию HTTP/2 фреймов'}], 'under_the_hood': 'gRPC-сервер читает заголовок `Content-Type: application/grpc` и мультиплексирует запросы по номерам Stream ID протокола HTTP/2.', 'pitfalls': 'Обычные L4-балансировщики не умеют балансировать HTTP/2 стримы, отправляя все запросы на один бэкенд, пока открыт сокет. Для gRPC требуется L7-балансировка (Envoy).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему классический круглый робин (Round-Robin) L4-балансировщика не работает с gRPC?»\n**Ответ:** gRPC держит одно постоянное TCP-соединение (Keep-Alive) и передает тысячи запросов внутри него в виде HTTP/2 стримов. L4 балансировщик балансирует только TCP-соединения, поэтому все запросы будут бесконечно идти на один и тот же под.'}, {'num': 111, 'title': 'Реализация легковесного прокси-сервера на стандартном http.Transport', 'task': 'Напишите простой прокси-сервер: принимает HTTP-запросы, перенаправляет их на целевой сервер, возвращает ответ клиенту.', 'theory': 'Простейший HTTP Forwarding Proxy без сторонних библиотек:\n1. Хендлер копирует входящий запрос `r`.\n2. Перенаправляет запрос на целевой сервер через `http.DefaultTransport.RoundTrip(outReq)`.\n3. Копирует полученные заголовки и статус в `w`.\n4. Копирует тело через `io.Copy(w, resp.Body)`.', 'step_by_step': '1. Запустим целевой сервер.\n2. Реализуем проксирующий обработчик.\n3. Скопируем статус, заголовки и тело.\n4. Проверим прозрачность проксирования.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"net/url"\n)\n\nfunc SimpleProxyHandler(target *url.URL) http.HandlerFunc {\n\treturn func(w http.ResponseWriter, r *http.Request) {\n\t\toutReq := r.Clone(r.Context())\n\t\toutReq.URL.Scheme = target.Scheme\n\t\toutReq.URL.Host = target.Host\n\t\toutReq.Host = target.Host\n\t\toutReq.RequestURI = "" // Очищаем для client.Do\n\n\t\tresp, err := http.DefaultTransport.RoundTrip(outReq)\n\t\tif err != nil {\n\t\t\thttp.Error(w, "Proxy Error", http.StatusBadGateway)\n\t\t\treturn\n\t\t}\n\t\tdefer resp.Body.Close()\n\n\t\t// Копируем заголовки ответа\n\t\tfor k, vv := range resp.Header {\n\t\t\tfor _, v := range vv {\n\t\t\t\tw.Header().Add(k, v)\n\t\t\t}\n\t\t}\n\t\tw.WriteHeader(resp.StatusCode)\n\t\t_, _ = io.Copy(w, resp.Body)\n\t}\n}\n\nfunc main() {\n\ttargetServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("X-Backend-Version", "v1.0.0")\n\t\tfmt.Fprint(w, "Ответ от конечного целевого сервера")\n\t}))\n\tdefer targetServer.Close()\n\n\ttargetURL, _ := url.Parse(targetServer.URL)\n\tproxyServer := httptest.NewServer(SimpleProxyHandler(targetURL))\n\tdefer proxyServer.Close()\n\n\tresp, _ := http.Get(proxyServer.URL)\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("[Status]            %d\\n", resp.StatusCode)\n\tfmt.Printf("[X-Backend-Version] %s\\n", resp.Header.Get("X-Backend-Version"))\n\tfmt.Printf("[Body]              %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status]            200\n# [X-Backend-Version] v1.0.0\n# [Body]              Ответ от конечного целевого сервера'}], 'under_the_hood': 'Метод `r.Clone(ctx)` создает глубокую копию структуры `http.Request`, включая клонирование карты заголовков `Header`.', 'pitfalls': "Поле `RequestURI` в исходящем `http.Request` клиента обязано быть пустым, иначе `RoundTrip` вернет ошибку `http: Request.RequestURI can't be set in client requests`.", 'bigtech_interview': '**Вопрос с собеседования:** «Зачем очищать RequestURI перед вызовом RoundTrip?»\n**Ответ:** `RequestURI` используется сервером только для чтения сырой строки запроса из TCP-сокета. На стороне клиента URL запроса берется строго из структуры `req.URL`. Наличие `RequestURI` вызывает ошибку валидации в рантайме Go.'}, {'num': 112, 'title': 'Многопоточный HTTP-краулер (BFS) с пулом горутин, семафором и sync.Map', 'task': 'Напиши **HTTP Crawler** (BFS): начинай с корневого URL, извлекай все ссылки (`href`) из HTML через `regexp` или `golang.org/x/net/html`. Ограничь глубину 2. Используй `sync.WaitGroup` + семафор (10 одновременных запросов). Сохраняй посещённые URL в `sync.Map`.', 'theory': 'Архитектура высоконагруженного веб-краулера:\n1. Потокобезопасная дедупликация через `sync.Map` (`LoadOrStore`).\n2. Ограничение конкурентности через семафор на канале `chan struct{}` (Rate Limiting сокетов).\n3. Синхронизация параллельных воркеров через `sync.WaitGroup`.\n4. Парсинг ссылок регулярным выражением `href="([^"]+)"`.', 'step_by_step': '1. Создадим мок-сервер с несколькими HTML страницами и ссылками.\n2. Инициализируем семафор `sem := make(chan struct{}, 3)`.\n3. Реализуем функцию рекурсивного краулинга с проверкой глубины.\n4. Выведем все обнаруженные и посещенные страницы.', 'code_blocks': [{'filename': 'crawler_demo.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"regexp"\n\t"sync"\n)\n\nvar hrefRegexp = regexp.MustCompile(`href="([^"]+)"`)\n\ntype Crawler struct {\n\tvisited sync.Map\n\tsem     chan struct{}\n\twg      sync.WaitGroup\n\tclient  *http.Client\n}\n\nfunc (c *Crawler) Crawl(url string, depth int) {\n\tdefer c.wg.Done()\n\tif depth <= 0 {\n\t\treturn\n\t}\n\n\t// Атомарно проверяем, посещали ли мы уже этот URL\n\tif _, loaded := c.visited.LoadOrStore(url, true); loaded {\n\t\treturn\n\t}\n\n\tc.sem <- struct{}{} // Захват слота семафора\n\tresp, err := c.client.Get(url)\n\t<-c.sem // Освобождение слота\n\n\tif err != nil {\n\t\treturn\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Crawled] %s (Глубина: %d)\\n", url, depth)\n\n\t// Извлекаем ссылки\n\tmatches := hrefRegexp.FindAllStringSubmatch(string(body), -1)\n\tfor _, m := range matches {\n\t\tlink := m[1]\n\t\tc.wg.Add(1)\n\t\tgo c.Crawl(link, depth-1)\n\t}\n}\n\nfunc main() {\n\tvar ts *httptest.Server\n\tts = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "text/html")\n\t\tswitch r.URL.Path {\n\t\tcase "/":\n\t\t\tfmt.Fprintf(w, `<a href="%s/page1">1</a> <a href="%s/page2">2</a>`, ts.URL, ts.URL)\n\t\tcase "/page1":\n\t\t\tfmt.Fprintf(w, `<a href="%s/page3">3</a>`, ts.URL)\n\t\tdefault:\n\t\t\tfmt.Fprint(w, "leaf page")\n\t\t}\n\t}))\n\tdefer ts.Close()\n\n\tcrawler := &Crawler{\n\t\tsem:    make(chan struct{}, 5),\n\t\tclient: ts.Client(),\n\t}\n\n\tcrawler.wg.Add(1)\n\tcrawler.Crawl(ts.URL, 3)\n\tcrawler.wg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run crawler_demo.go\n# Вывод:\n# [Crawled] http://127.0.0.1:... (Глубина: 3)\n# [Crawled] http://127.0.0.1:.../page1 (Глубина: 2)\n# [Crawled] http://127.0.0.1:.../page2 (Глубина: 2)\n# [Crawled] http://127.0.0.1:.../page3 (Глубина: 1)'}], 'under_the_hood': 'Канал `sem chan struct{}` с буфером 5 ограничивает число одновременно активных TCP-запросов, предотвращая исчерпание пула файловых дескрипторов (ulimit -n).', 'pitfalls': 'В реальном краулере парсить HTML регулярками опасно: некорректный HTML или комментарии ломают парсинг. Следует использовать пакет `golang.org/x/net/html`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему sync.Map идеально подходит для кэша посещенных URL в краулере?»\n**Ответ:** `sync.Map` оптимизирована для сценариев, когда ключи записываются один раз, а затем многократно читаются многими горутинами, устраняя блокировки кэш-линий процессора благодаря двухуровневой структуре (read-only map + dirty map).'}, {'num': 113, 'title': 'Анализ ошибки x509: certificate signed by unknown authority и кастомный Transport', 'task': '**[Каверзный кейс]**: Напиши HTTPS-клиента, который делает запрос к твоему самоподписанному серверу. Поймай ошибку проверки сертификата (`x509: certificate signed by unknown authority`). Исправь клиент, создав кастомный `http.Transport` с `InsecureSkipVerify: true`. Объясни, почему это опасно в production.', 'theory': 'Природа ошибки `x509: certificate signed by unknown authority`:\nОперационная система и рантайм Go не доверяют сертификату, если его издатель (Issuer) не входит в системное хранилище доверенных корневых центров сертификации (Root CA).\nОтключение проверки через `InsecureSkipVerify: true` делает соединение полностью прозрачным для любого перехватчика трафика.', 'step_by_step': '1. Запустим `httptest.NewTLSServer`.\n2. Выполним запрос через `http.DefaultClient` и поймаем ошибку x509.\n3. Исправим клиент через кастомный `http.Transport`.\n4. Убедимся в успешном соединении.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/tls"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tserver := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Secure Hello")\n\t}))\n\tdefer server.Close()\n\n\t// 1. Стандартный клиент падает с ошибкой x509\n\t_, err := http.Get(server.URL)\n\tif err != nil {\n\t\tfmt.Printf("[Ожидаемая ошибка безопасности] %v\\n", err)\n\t}\n\n\t// 2. Исправление для тестовой среды\n\tinsecureClient := &http.Client{\n\t\tTransport: &http.Transport{\n\t\t\tTLSClientConfig: &tls.Config{InsecureSkipVerify: true},\n\t\t},\n\t}\n\n\tres, err := insecureClient.Get(server.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer res.Body.Close()\n\n\tfmt.Printf("[Успешное подключение] Статус: %d\\n", res.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Ожидаемая ошибка безопасности] Get "...": tls: failed to verify certificate: x509: certificate signed by unknown authority\n# [Успешное подключение] Статус: 200'}], 'under_the_hood': 'Валидатор сертификатов Go строит цепочку доверия от конечного сертификата до корня. Если корень не найден в `systemRoots`, валидатор возвращает ошибку `x509.UnknownAuthorityError`.', 'pitfalls': 'В корпоративных сетях с инспекцией SSL (Корпоративный MITM) без добавления сертификата компании в системное хранилище Go все сетевые утилиты перестают работать.', 'bigtech_interview': '**Вопрос с собеседования:** «Где Go берет доверенные корневые сертификаты на Linux?»\n**Ответ:** В стандартных путях дистрибутива: `/etc/ssl/certs/ca-certificates.crt`, `/etc/pki/tls/certs/ca-bundle.crt` или встроенном наборе `crypto/x509/internal/cacerts`.'}, {'num': 114, 'title': 'Логирующий Middleware: извлечение IP-клиента через RemoteAddr и замер Latency', 'task': '**Логирующий Middleware**: Напишите функцию-декоратор (Middleware) для вашего сервера. Она должна оборачивать любые HTTP-обработчики и записывать в лог: метод запроса, запрашиваемый путь, IP-адрес клиента и время, затраченное на обработку запроса.', 'theory': 'Извлечение IP-адреса:\nПоле `r.RemoteAddr` содержит строку `"IP:port"`. Для чистого получения IP-адреса используется функция `net.SplitHostPort(r.RemoteAddr)`.', 'step_by_step': '1. Напишем `AccessLogMiddleware`.\n2. Извлечем IP через `net.SplitHostPort`.\n3. Замерим время выполнения запроса.\n4. Проверим форматированный вывод.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc AccessLogMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tstart := time.Now()\n\n\t\tip, _, err := net.SplitHostPort(r.RemoteAddr)\n\t\tif err != nil {\n\t\t\tip = r.RemoteAddr\n\t\t}\n\n\t\tnext.ServeHTTP(w, r)\n\n\t\tduration := time.Since(start)\n\t\tfmt.Printf("[ACCESS LOG] IP: %-15s | %-4s %-12s | Time: %v\\n",\n\t\t\tip, r.Method, r.URL.Path, duration.Round(time.Microsecond))\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(2 * time.Millisecond)\n\t\tfmt.Fprint(w, "Users List")\n\t})\n\n\tserver := httptest.NewServer(AccessLogMiddleware(mux))\n\tdefer server.Close()\n\n\tres, _ := http.Get(server.URL + "/users")\n\tres.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [ACCESS LOG] IP: 127.0.0.1       | GET  /users       | Time: 2ms'}], 'under_the_hood': '`net.SplitHostPort` корректно обрабатывает как IPv4 (`127.0.0.1:1234`), так и IPv6 (`[::1]:1234`) адреса.', 'pitfalls': 'Попытка разделить адрес по обычному двоеточию `strings.Split(r.RemoteAddr, ":")` ломает IPv6-адреса, содержащие множество двоеточий.', 'bigtech_interview': '**Вопрос с собеседования:** «Как получить настоящий IP-адрес клиента, если сервис стоит за Cloudflare или Nginx?»\n**Ответ:** Проверять заголовки `CF-Connecting-IP`, `X-Real-IP` или первый IP-адрес из цепочки `X-Forwarded-For`, но строго доверяя этим заголовкам только в том случае, если запрос пришел от доверенного внутреннего балансировщика.'}, {'num': 115, 'title': 'HTTP Load Balancer (Round-Robin) с атомарным распределением трафика на ReverseProxy', 'task': 'Напиши **HTTP Load Balancer** (round-robin): слушает `:8080`, имеет пул бэкендов (`localhost:9001`, `9002`, `9003`). Каждый новый запрос идёт на следующий бэкенд (атомарный счётчик). Используй `httputil.ReverseProxy` + `sync/atomic`.', 'theory': 'Алгоритм циклического распределения нагрузки Round-Robin:\nКаждый новый запрос направляется на бэкенд по формуле:\n$\\text{index} = \\text{atomic.AddUint64}(\\&counter, 1) \\pmod N$\nЭто гарантирует равномерное распределение трафика между $N$ репликами без состояния гонки.', 'step_by_step': '1. Создадим три тестовых сервера бэкенда.\n2. Создадим массив `[]*httputil.ReverseProxy`.\n3. Реализуем балансировщик с атомарным счетчиком `atomic.Uint64`.\n4. Отправим 6 запросов и убедимся в чередовании серверов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"net/http/httputil"\n\t"net/url"\n\t"sync/atomic"\n)\n\ntype RoundRobinBalancer struct {\n\tbackends []*httputil.ReverseProxy\n\tcounter  atomic.Uint64\n}\n\nfunc NewRoundRobinBalancer(targets []*url.URL) *RoundRobinBalancer {\n\tvar proxies []*httputil.ReverseProxy\n\tfor _, target := range targets {\n\t\tproxies = append(proxies, httputil.NewSingleHostReverseProxy(target))\n\t}\n\treturn &RoundRobinBalancer{backends: proxies}\n}\n\nfunc (b *RoundRobinBalancer) ServeHTTP(w http.ResponseWriter, r *http.Request) {\n\tidx := b.counter.Add(1) % uint64(len(b.backends))\n\tb.backends[idx].ServeHTTP(w, r)\n}\n\nfunc main() {\n\t// Поднимаем 3 тестовых бэкенда\n\tvar targets []*url.URL\n\tfor i := 1; i <= 3; i++ {\n\t\tname := fmt.Sprintf("Backend-%d", i)\n\t\tsrv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tfmt.Fprintf(w, "Ответил: %s", name)\n\t\t}))\n\t\tdefer srv.Close()\n\t\tu, _ := url.Parse(srv.URL)\n\t\ttargets = append(targets, u)\n\t}\n\n\tbalancer := NewRoundRobinBalancer(targets)\n\tlbServer := httptest.NewServer(balancer)\n\tdefer lbServer.Close()\n\n\t// Отправляем 6 запросов\n\tfor reqNum := 1; reqNum <= 6; reqNum++ {\n\t\tres, _ := http.Get(lbServer.URL)\n\t\tbody, _ := io.ReadAll(res.Body)\n\t\tres.Body.Close()\n\t\tfmt.Printf("Запрос #%d -> %s\\n", reqNum, string(body))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запрос #1 -> Ответил: Backend-2\n# Запрос #2 -> Ответил: Backend-3\n# Запрос #3 -> Ответил: Backend-1\n# Запрос #4 -> Ответил: Backend-2\n# Запрос #5 -> Ответил: Backend-3\n# Запрос #6 -> Ответил: Backend-1'}], 'under_the_hood': '`atomic.Uint64.Add` выполняется как одна процессорная инструкция `LOCK XADD` на x86_64, гарантируя потокобезопасность на миллионах rps без блокировок мьютекса.', 'pitfalls': 'Если один из бэкендов падает, простой Round-Robin продолжит слать на него каждый $N$-й запрос. Требуется внедрение Health Checking для динамического исключения мертвых узлов.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда Least Connections эффективнее Round-Robin?»\n**Ответ:** При неравномерной длительности запросов (например, один запрос скачивает гигабайтный файл 30 секунд, а другой отдает 1 КБ за 1 мс). Round-Robin перегрузит сервер, на который случайно попало несколько тяжелых запросов, тогда как Least Connections направит новый запрос на наименее занятый бэкенд.'}, {'num': 116, 'title': 'Server Streaming RPC: непрерывная потоковая передача тикеров времени клиенту', 'task': 'Реализуйте **Server Streaming RPC**: клиент отправляет один запрос, а сервер потоком отправляет множество ответов (например, тикеры времени или ленту новостей).', 'theory': 'Паттерн Server Streaming:\nКлиент делает один HTTP-запрос. Сервер оставляет соединение открытым и непрерывно передает поток сообщений (чанки или SSE фреймы) клиенту по мере их генерации.', 'step_by_step': '1. Создадим обработчик потока.\n2. Проверим поддержку интерфейса `http.Flusher`.\n3. В цикле отправим 4 тика с паузой.\n4. Клиент вычитает поток в реальном времени.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc streamTimeTicks(w http.ResponseWriter, r *http.Request) {\n\tflusher, ok := w.(http.Flusher)\n\tif !ok {\n\t\thttp.Error(w, "Streaming not supported", http.StatusInternalServerError)\n\t\treturn\n\t}\n\n\tw.Header().Set("Content-Type", "text/plain")\n\tw.Header().Set("Transfer-Encoding", "chunked")\n\n\tfor i := 1; i <= 3; i++ {\n\t\tfmt.Fprintf(w, "Тик #%d: %s\\n", i, time.Now().Format("15:04:05.000"))\n\t\tflusher.Flush()\n\t\ttime.Sleep(25 * time.Millisecond)\n\t}\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(streamTimeTicks))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tdefer resp.Body.Close()\n\n\tscanner := bufio.NewScanner(resp.Body)\n\tfor scanner.Scan() {\n\t\tfmt.Printf("[Stream Chunk Received] %s\\n", scanner.Text())\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Stream Chunk Received] Тик #1: ...\n# [Stream Chunk Received] Тик #2: ...\n# [Stream Chunk Received] Тик #3: ...'}], 'under_the_hood': 'Заголовок `Transfer-Encoding: chunked` в HTTP/1.1 позволяет передавать данные неопределенной длины частями без указания `Content-Length`.', 'pitfalls': 'Не буферизуйте вывод на стороне прокси: в Nginx для стриминга необходимо отключать буферизацию `proxy_buffering off;` или выставлять заголовок `X-Accel-Buffering: no`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как Server Streaming реализован в gRPC под капотом?»\n**Ответ:** Клиент шлет один HTTP/2 HEADERS фрейм с методом. Сервер отвечает HEADERS фреймом, а затем шлет множество HTTP/2 DATA фреймов с бинарными Protobuf сообщениями. В конце сервер отправляет трейлер HEADERS с `grpc-status: 0` (OK).'}, {'num': 117, 'title': 'WebSocket Broadcast сервер: потокобезопасная трансляция сообщений по пулу клиентов', 'task': 'Реализуйте WebSocket-сервер: клиенты подключаются, могут отправлять сообщения, а сервер транслирует их всем (простой чат на WebSocket). Используйте `golang.org/x/net/websocket` или `gorilla/websocket`.', 'theory': 'Широковещательная рассылка (Broadcasting):\nПри получении сообщения сервер в цикле рассылает его всем активным соединениям из пула. Для защиты списка соединений используется `sync.RWMutex`.', 'step_by_step': '1. Создадим менеджер соединений `BroadcastServer`.\n2. Реализуем добавление и удаление клиентов.\n3. Продемонстрируем рассылку одного сообщения группе клиентов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype Connection struct {\n\tID      string\n\tOutbox  chan string\n}\n\ntype Broadcaster struct {\n\tmu    sync.RWMutex\n\tconns map[string]*Connection\n}\n\nfunc (b *Broadcaster) Join(c *Connection) {\n\tb.mu.Lock()\n\tb.conns[c.ID] = c\n\tb.mu.Unlock()\n}\n\nfunc (b *Broadcaster) Broadcast(text string) {\n\tb.mu.RLock()\n\tdefer b.mu.RUnlock()\n\n\tfor _, c := range b.conns {\n\t\tselect {\n\t\tcase c.Outbox <- text:\n\t\tdefault:\n\t\t\t// Защита от зависших каналов\n\t\t}\n\t}\n}\n\nfunc main() {\n\tb := &Broadcaster{conns: make(map[string]*Connection)}\n\n\tu1 := &Connection{ID: "user_1", Outbox: make(chan string, 2)}\n\tu2 := &Connection{ID: "user_2", Outbox: make(chan string, 2)}\n\n\tb.Join(u1)\n\tb.Join(u2)\n\n\tb.Broadcast("Системное оповещение: сервер перезагрузится через 5 минут")\n\n\tfmt.Println("User 1 получил:", <-u1.Outbox)\n\tfmt.Println("User 2 получил:", <-u2.Outbox)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# User 1 получил: Системное оповещение: сервер перезагрузится через 5 минут\n# User 2 получил: Системное оповещение: сервер перезагрузится через 5 минут'}], 'under_the_hood': 'Каналы с буфером сглаживают пики активности рассылки сообщений.', 'pitfalls': 'Удержание `b.mu.RLock()` во время долгой блокирующей записи в сеть приведет к дедлоку всей системы.', 'bigtech_interview': '**Вопрос с собеседования:** «Как избежать дедлока при широковещательной рассылке миллиону клиентов?»\n**Ответ:** Вынести сетевую отправку в отдельную горутину-писатель (writePump) для каждого клиента. Хаб рассылки только складывает указатель на сообщение в буферизированный канал клиента без ожидания фактической отправки в сокет.'}, {'num': 118, 'title': 'HTTP Cache Proxy: кэширование ответов в памяти с проверкой TTL и Cache-Control', 'task': 'Напиши **HTTP Cache Proxy**: слушает `:8080`, проверяет кеш (`map[string]cachedResponse` + `sync.RWMutex`) перед проксированием. Если ответ в кеше и не протух — верни из кеша. Иначе — проксируй, сохрани в кеш с TTL. Используй `Cache-Control` заголовки.', 'theory': 'Кэширующий прокси-сервер (Caching Reverse Proxy):\n1. Проверяет наличие ответа в in-memory кэше по ключу `r.URL.Path`.\n2. Если кэш валиден (`time.Now().Before(expiresAt)`), возвращает ответ со статусом `X-Cache: HIT`.\n3. При промахе (`X-Cache: MISS`) пересылает запрос бэкенду, кэширует тело и отдает клиенту.', 'step_by_step': '1. Создадим структуру `CachedEntry` со сроком экспирации.\n2. Реализуем проверку кэша с `sync.RWMutex`.\n3. Запросим ресурс дважды и зафиксируем HIT на втором вызове.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"sync"\n\t"time"\n)\n\ntype CacheItem struct {\n\tBody      []byte\n\tExpiresAt time.Time\n}\n\ntype CachingProxy struct {\n\tmu      sync.RWMutex\n\tstorage map[string]CacheItem\n\tbackend *httptest.Server\n}\n\nfunc (p *CachingProxy) ServeHTTP(w http.ResponseWriter, r *http.Request) {\n\tkey := r.URL.Path\n\n\tp.mu.RLock()\n\titem, found := p.storage[key]\n\tp.mu.RUnlock()\n\n\tif found && time.Now().Before(item.ExpiresAt) {\n\t\tw.Header().Set("X-Cache", "HIT")\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write(item.Body)\n\t\treturn\n\t}\n\n\t// Cache MISS -> идем на бэкенд\n\tresp, err := http.Get(p.backend.URL + key)\n\tif err != nil {\n\t\thttp.Error(w, "Gateway Error", http.StatusBadGateway)\n\t\treturn\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\n\t// Сохраняем в кэш с TTL 1 минута\n\tp.mu.Lock()\n\tp.storage[key] = CacheItem{\n\t\tBody:      body,\n\t\tExpiresAt: time.Now().Add(1 * time.Minute),\n\t}\n\tp.mu.Unlock()\n\n\tw.Header().Set("X-Cache", "MISS")\n\tw.WriteHeader(resp.StatusCode)\n\t_, _ = w.Write(body)\n}\n\nfunc main() {\n\tbackend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Динамический контент бэкенда")\n\t}))\n\tdefer backend.Close()\n\n\tproxy := &CachingProxy{\n\t\tstorage: make(map[string]CacheItem),\n\t\tbackend: backend,\n\t}\n\tproxyServer := httptest.NewServer(proxy)\n\tdefer proxyServer.Close()\n\n\t// 1. Первый запрос (MISS)\n\tr1, _ := http.Get(proxyServer.URL + "/news")\n\tfmt.Printf("[Запрос 1] X-Cache: %s\\n", r1.Header.Get("X-Cache"))\n\tr1.Body.Close()\n\n\t// 2. Второй запрос (HIT)\n\tr2, _ := http.Get(proxyServer.URL + "/news")\n\tfmt.Printf("[Запрос 2] X-Cache: %s\\n", r2.Header.Get("X-Cache"))\n\tr2.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Запрос 1] X-Cache: MISS\n# [Запрос 2] X-Cache: HIT'}], 'under_the_hood': 'Чтение из кэша с `RLock` выполняется параллельно сотнями горутин без взаимных блокировок.', 'pitfalls': 'Кэширование ответов с заголовком `Set-Cookie` или приватными данными пользователей — критическая уязвимость утечки сессий между клиентами.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое Cache Stampede (Dog-piling) и как от него защититься в Go?»\n**Ответ:** Ситуация, когда в момент истечения TTL популярного ключа кэша тысячи параллельных запросов одновременно получают MISS и все вместе бегут в базу данных, роняя её. Решение: использование библиотеки `golang.org/x/sync/singleflight`, которая объединяет параллельные запросы к одному ключу в один единственный запрос к бэкенду.'}, {'num': 119, 'title': 'Bidirectional Streaming RPC: концепция двунаправленного полнодуплексного обмена', 'task': 'Реализуйте **Bidirectional Streaming RPC**: клиент и сервер одновременно отправляют друг другу потоки сообщений (например, для реализации многопользовательской игры или чата).', 'theory': 'Двунаправленный стриминг (Bidirectional Streaming RPC):\nИ клиент, и сервер могут в любой момент времени отправлять сообщения независимо друг от друга в рамках одного сетевого стрима HTTP/2 без ожидания ответа.', 'step_by_step': '1. Создадим два канала сообщений для эмуляции дуплексного стрима.\n2. Запустим горутину генерации серверных событий.\n3. Запустим горутину клиентских отправлений.\n4. Продемонстрируем параллельный обмен.', 'code_blocks': [{'filename': 'bidi_stream.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tclientToServer := make(chan string, 3)\n\tserverToClient := make(chan string, 3)\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\t// Клиентская горутина (пишет и читает)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tclientToServer <- "Ping 1"\n\t\tclientToServer <- "Ping 2"\n\t\tclose(clientToServer)\n\n\t\tfor msg := range serverToClient {\n\t\t\tfmt.Printf(" [Client] Получено: %s\\n", msg)\n\t\t}\n\t}()\n\n\t// Серверная горутина (читает и пишет)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor msg := range clientToServer {\n\t\t\tfmt.Printf("   [Server] Обработано: %s\\n", msg)\n\t\t\tserverToClient <- "Pong on " + msg\n\t\t}\n\t\tclose(serverToClient)\n\t}()\n\n\twg.Wait()\n\ttime.Sleep(10 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run bidi_stream.go\n# Вывод:\n#    [Server] Обработано: Ping 1\n#    [Server] Обработано: Ping 2\n#  [Client] Получено: Pong on Ping 1\n#  [Client] Получено: Pong on Ping 2'}], 'under_the_hood': 'В HTTP/2 двунаправленный стриминг реализуется за счет чередования фреймов DATA с одинаковым Stream Identifier в обоих направлениях TCP-соединения.', 'pitfalls': 'Если одна из сторон забыла закрыть свой стрим (`CloseSend()`), вторая сторона зависнет в ожидании `io.EOF`.', 'bigtech_interview': '**Вопрос с собеседования:** «Чем Bidirectional gRPC стриминг отличается от WebSocket?»\n**Ответ:** gRPC работает со строгой схемой Protobuf и генерирует типизированный клиентский код для 10+ языков программирования, а также поддерживает встроенную отмену через `Context` и метаданные. WebSocket — более низкоуровневый протокол передачи сырых текстовых/бинарных кадров.'}, {'num': 120, 'title': 'Финальная архитектура Panic Recovery Middleware с красивым JSON-ответом 500', 'task': '**Panic Recovery Middleware**: Если в хендлере случится паника (например, обращение к nil-слайсу), весь сервер не упадет (Go сам восстановит горутину), но клиент просто получит пустой ответ. Напиши Middleware, которая делает `defer func(){ if err := recover(); ... }()`, логирует панику и красиво отдает клиенту "500 Internal Server Error".', 'theory': 'Стандартное поведение `net/http` без кастомного recovery:\nПри панике сервер логирует ошибку в `stderr` и обрывает TCP-сокет. Клиент в браузере или API видит сетевую ошибку `Empty reply from server` или `ERR_EMPTY_RESPONSE`.\nКастомный Recovery Middleware обязан перехватить панику и гарантированно отдать клиенту валидный ответ:\nHTTP 500 с телом `{"error": "Internal Server Error"}`.', 'step_by_step': '1. Реализуем `PanicRecoveryJSON`.\n2. В `defer` вызовем `recover()`.\n3. Установим `Content-Type: application/json` и статус 500.\n4. Проверим получение красивого JSON-ответа на клиенте.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc PanicRecoveryJSON(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tdefer func() {\n\t\t\tif rec := recover(); rec != nil {\n\t\t\t\tfmt.Printf("[CRITICAL ERROR] Перехвачена паника: %v\\n", rec)\n\n\t\t\t\tw.Header().Set("Content-Type", "application/json")\n\t\t\t\tw.WriteHeader(http.StatusInternalServerError)\n\t\t\t\t_, _ = w.Write([]byte(`{"code":500,"error":"Internal Server Error","message":"На сервере произошел непредвиденный сбой"}`))\n\t\t\t}\n\t\t}()\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/bug", func(w http.ResponseWriter, r *http.Request) {\n\t\tvar list []int\n\t\t_ = list[10] // Паника: index out of range!\n\t})\n\n\tserver := httptest.NewServer(PanicRecoveryJSON(mux))\n\tdefer server.Close()\n\n\tresp, _ := http.Get(server.URL + "/bug")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("[Client Status] %d\\n", resp.StatusCode)\n\tfmt.Printf("[Client JSON]   %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [CRITICAL ERROR] Перехвачена паника: runtime error: index out of range [10] with length 0\n# [Client Status] 500\n# [Client JSON]   {"code":500,"error":"Internal Server Error","message":"На сервере произошел непредвиденный сбой"}'}], 'under_the_hood': 'Паника индекса среза транслируется рантаймом Go в вызов `runtime.panicIndex`, который перехватывается отложенной функцией `defer`.', 'pitfalls': 'Никогда не выводите подробный стек-трейс или переменные окружения в ответ клиенту, так как это раскрывает внутренности системы и пароли злоумышленникам.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в продакшене нельзя отдавать клиенту реальный текст паники?»\n**Ответ:** Это уязвимость утечки информации (CWE-209 / Information Exposure Through an Error Message). Текст паники может содержать фрагменты SQL-запросов, пути к исходникам на сервере, адреса внутренних хостов и пароли. Клиенту отдают абстрактный код ошибки, а полный трейс пишут в закрытый централизованный лог (ELK/Sentry).'}]
